(deftest hosted-core-app-runs-user-functions-and-builtins
  (let [path (fixture "accepted/core-app.gravity")
        artifact (bootstrap/hosted-core-app-proof-file-artifact path)
        proof (:capability-based-proof artifact)]
    (is (= :gravity/stage0-hosted-core-app-proof (:kind artifact)))
    (is (= "P01-S1" (:task artifact)))
    (is (= 'core.app (get-in artifact [:module :module])))
    (is (= :hosted (get-in artifact [:module :profile])))
    (is (= "core-app\ngravity:19:2\n(:ok 19)\n"
           (bootstrap/run-file path)))
    (is (= "core-app\ngravity:19:2\n(:ok 19)\n"
           (get-in artifact [:accepted-run :stdout])))
    (is (= '[build-record render total]
           (get-in artifact [:runtime-surface :user-functions])))
    (is (set/subset?
         '#{+ * > str pr-str hash-map vector list conj assoc get count}
         (set (get-in artifact [:runtime-surface :builtin-functions]))))
    (is (true? (:hosted-core-runner-executed? proof)))
    (is (true? (:user-functions-callable? proof)))
    (is (true? (:builtin-calls-supported? proof)))
    (is (true? (:control-flow-supported? proof)))
    (is (true? (:effects-and-capabilities-checked? proof)))
    (is (true? (:rejected-diagnostics-covered? proof)))
    (is (true? (get-in proof [:limitations :clojure-hosted-runner?])))
    (is (false? (get-in proof [:limitations :self-hosted-compiler?])))
    (is (= :replace-hosted-core-runner-with-gravity-compiled-execution
           (get-in proof [:limitations :next-required-capability])))
    (is (re-find #"^sha256:" (:artifact-id artifact)))))

