                     [key {:status :verified}])
                   bootstrap/p15-s23-whole-language-self-hosting-required-evidence))
        complete-candidate
        {:candidate-id :complete-self-hosting-evidence-fixture
         :scope :whole-language-compiler
         :full-language-compiler-self-hosted? true
         :clojure-seed-retired? true
         :clojure-seed-boundary? false
