        (bootstrap/p15-s23-stage2-plan-emitter-file-artifact
         bootstrap/p15-s23-compiler-source-path)
        records
        (:rejected-p15-s23-stage2-plan-emitter-fixtures artifact)
        by-fixture (into {} (map (juxt :fixture identity) records))
        missing
        (get by-fixture
             :internal-p15-s23-stage2-plan-emitter-missing-contract)
        rule-gap
        (get by-fixture
             :internal-p15-s23-stage2-plan-emitter-rule-gap)
        output-gap
        (get by-fixture
             :internal-p15-s23-stage2-plan-emitter-output-gap)
        rejected-gap
        (get by-fixture
             :internal-p15-s23-stage2-plan-emitter-rejected-gap)
        evidence-gap
        (get by-fixture
             :internal-p15-s23-stage2-plan-emitter-evidence-gap)
        preservation-gap
        (get by-fixture
             :internal-p15-s23-stage2-plan-emitter-preservation-gap)
        boundary-gap
        (get by-fixture
             :internal-p15-s23-stage2-plan-emitter-boundary-gap)
        overclaim
        (get by-fixture
             :internal-p15-s23-stage2-plan-emitter-overclaim)]
    (is (= "P15S23Q001" (:expected-diagnostic missing)))
    (is (contains? (set (map :diagnostic (:diagnostics missing)))
                   "P15S23Q001"))
    (is (= "P15S23Q002" (:expected-diagnostic rule-gap)))
    (is (contains? (set (map :diagnostic (:diagnostics rule-gap)))
                   "P15S23Q002"))
    (is (= "P15S23Q003" (:expected-diagnostic output-gap)))
    (is (contains? (set (map :diagnostic (:diagnostics output-gap)))
                   "P15S23Q003"))
    (is (= "P15S23Q004" (:expected-diagnostic rejected-gap)))
    (is (contains? (set (map :diagnostic (:diagnostics rejected-gap)))
                   "P15S23Q004"))
    (is (= "P15S23Q005" (:expected-diagnostic evidence-gap)))
    (is (contains? (set (map :diagnostic (:diagnostics evidence-gap)))
                   "P15S23Q005"))
    (is (= "P15S23Q006" (:expected-diagnostic preservation-gap)))
    (is (contains? (set (map :diagnostic (:diagnostics preservation-gap)))
                   "P15S23Q006"))
    (is (= "P15S23Q007" (:expected-diagnostic boundary-gap)))
    (is (contains? (set (map :diagnostic (:diagnostics boundary-gap)))
                   "P15S23Q007"))
	    (is (= "P15S23Q008" (:expected-diagnostic overclaim)))
	    (is (contains? (set (map :diagnostic (:diagnostics overclaim)))
	                   "P15S23Q008"))))

(deftest p15-s23-stage2-runtime-recur-signal-rejects-mixed-key-maps-safely
  (let [lookup
        (var-get
         (ns-resolve
          'gravity.bootstrap
          'p15-s23-stage2-runtime-map-entry))
        large-map
        (into {}
              (map (fn [index] [(keyword (str "entry-" index)) index]))
              (range 10000))
        nil-entry (lookup (assoc large-map :requested nil) :requested)]
    (is (false?
         (bootstrap/p15-s23-stage2-runtime-recur-signal?
          (sorted-map 'artifact :unrelated))))
    (is (true?
         (bootstrap/p15-s23-stage2-runtime-recur-signal?
          (bootstrap/p15-s23-stage2-runtime-recur-signal [1 2 3]))))
    (is (= :requested (key nil-entry)))
    (is (nil? (val nil-entry)))
    (is (nil? (lookup large-map :absent)))
    (is (nil? (lookup [:not-a-map] :requested)))
    (is (= ['artifact :unrelated]
           (vec (lookup (sorted-map 'artifact :unrelated)
                        'artifact))))))

	(deftest p15-s23-stage2-runtime-kernel-records-executable-proof
	  (let [artifact
	        (bootstrap/p15-s23-stage2-runtime-kernel-file-artifact
	         bootstrap/p15-s23-compiler-source-path)
	        proof (:capability-based-proof artifact)
	        rules (:rule-record artifact)
	        accepted (:accepted-record artifact)
	        rejected (:rejected-record artifact)
	        boundary (:boundary-record artifact)
	        results (:p15-s23-stage2-runtime-kernel-results artifact)
	        diagnostics
	        (set (map :diagnostic
	                  (get-in artifact
	                          [:p15-s23-stage2-runtime-kernel-diagnostic-stream
	                           :diagnostics])))
	        rejected-diagnostics
	        (set (mapcat #(map :diagnostic (:diagnostics %))
	                     (:rejected-p15-s23-stage2-runtime-kernel-fixtures
	                      artifact)))
	        runtime-rejected-diagnostics
	        (set (map :diagnostic
	                  (:verified-p15-s23-stage2-runtime-kernel-rejected-fixtures
	                   artifact)))]
	    (is (= :gravity/p15-s23-stage2-runtime-kernel-artifact
	           (:kind artifact)))
	    (is (= "P15-S23" (:task artifact)))
	    (is (= :p15-s23-stage2-runtime-kernel (:stage artifact)))
	    (is (= :gravity/stage2-runtime-kernel
	           (get-in artifact [:kernel-contract :artifact])))
	    (is (= :complete (:status rules)))
	    (is (true? (:rule-set-complete? rules)))
	    (is (= :complete (:status accepted)))
	    (is (true? (:stage2-runtime-kernel-executed? accepted)))
	    (is (true? (:entrypoint-result-equivalent? accepted)))
	    (is (true? (:instruction-summary-equivalent? accepted)))
	    (is (true? (:effect-summary-equivalent? accepted)))
	    (is (true? (:accepted-output-equivalent? accepted)))
	    (is (= bootstrap/p15-s23-accepted-app-expected-stdout
	           (:stage2-runtime-kernel-output accepted)))
	    (is (= bootstrap/p15-s23-accepted-app-expected-stdout
	           (:stage0-instruction-runner-output accepted)))
	    (is (= :complete (:status rejected)))
	    (is (= #{"L2-FUNCTION-ARITY" "L2-BUILTIN-ARITY"}
	           (set (:observed-diagnostics rejected))))
	    (is (= #{"L2-FUNCTION-ARITY" "L2-BUILTIN-ARITY"}
	           runtime-rejected-diagnostics))
	    (is (= :complete (:status boundary)))
	    (is (true? (:stage2-runtime-kernel-used? boundary)))
	    (is (true? (:stage2-runtime-host-replaced? boundary)))
	    (is (true? (:stage2-runtime-primitives-replaced? boundary)))
	    (is (false? (:clojure-stage0-runtime-host? boundary)))
	    (is (false? (:clojure-host-primitive-boundary? boundary)))
	    (is (true? (:gravity-runtime-primitives? boundary)))
	    (is (true? (:clojure-stage0-verifier? boundary)))
	    (is (true? (:clojure-stage0-compiler? boundary)))
	    (is (false? (:full-language-compiler-self-hosted? boundary)))
	    (is (false? (:clojure-seed-retired? boundary)))
	    (is (= 1 (:accepted-fixtures results)))
	    (is (= 2 (:rejected-fixtures results)))
	    (is (= 8 (:internal-rejected-fixtures results)))
	    (is (= #{"P15S23K001" "P15S23K002" "P15S23K003"
	             "P15S23K004" "P15S23K005" "P15S23K006"
	             "P15S23K007" "P15S23K008"}
	           diagnostics))
	    (is (= #{"P15S23K001" "P15S23K002" "P15S23K003"
	             "P15S23K004" "P15S23K005" "P15S23K006"
	             "P15S23K007" "P15S23K008"}
	           rejected-diagnostics))
	    (is (true? (:stage2-runtime-kernel-authored-in-gravity? proof)))
	    (is (true? (:stage2-runtime-kernel-present? proof)))
	    (is (true? (:stage2-runtime-kernel-executed? proof)))
	    (is (true? (:stage2-runtime-host-replaced? proof)))
	    (is (true? (:stage2-runtime-primitives-replaced? proof)))
	    (is (true? (:gravity-runtime-primitives-used? proof)))
	    (is (true? (:does-not-use-clojure-stage0-runtime-host? proof)))
	    (is (true? (:does-not-use-clojure-runtime-primitives? proof)))
	    (is (true? (:accepted-output-equivalent? proof)))
	    (is (true? (:rejected-diagnostics-equivalent? proof)))
	    (is (true? (:does-not-claim-full-self-hosting? proof)))
	    (is (true? (:does-not-claim-clojure-seed-retirement? proof)))
	    (is (true? (:rejected-candidates-covered? proof)))
	    (is (true? (:diagnostics-covered? proof)))
	    (is (true?
	         (get-in proof
	                 [:limitations
	                  :stage2-runtime-kernel-authored-in-gravity?])))
	    (is (true?
	         (get-in proof
	                 [:limitations :stage2-runtime-kernel-executed?])))
	    (is (true?
	         (get-in proof
	                 [:limitations :stage2-runtime-host-replaced?])))
	    (is (true?
	         (get-in proof
	                 [:limitations :stage2-runtime-primitives-replaced?])))
	    (is (true?
	         (get-in proof
	                 [:limitations :gravity-runtime-primitives?])))
	    (is (false?
	         (get-in proof
	                 [:limitations :clojure-stage0-runtime-host?])))
	    (is (false?
	         (get-in proof
	                 [:limitations :clojure-host-primitive-boundary?])))
	    (is (= :implement_whole_language_compiler_stage_without_clojure_seed
	           (get-in proof [:limitations :next-required-capability])))))

