      (is (= "🙂x" (:raw first-token)))
      (is (= 3 (get-in first-token [:span :end :column])))
      (is (= 4 (get-in last-token [:span :start :column])))
      (is (= :unicode-scalar
             (get-in first-token [:span :end :column-unit]))))))

