      {token-index-var
       (fn [tokens]
         (swap! index-builds inc)
         (original-token-index tokens))}
      (fn []
        (doseq [[ordinal suffix] (map-indexed vector [".gravity" ".qst"])]
          (let [path (str project-root "/src/reference-source" suffix)
                artifact
                (bootstrap/compiler-c2-reader-source-artifact
                 path source project-context)
                reference-values
                (mapv :form (bootstrap/read-source-form-records path source))
                table (bootstrap/stage1-reader-table)
                fallback-stream
                (bootstrap/stage1-reader-token-stream
                 path source table bootstrap/standard-reader-options)
                fallback-products
                (bootstrap/stage1-reader-products-from-token-stream
                 path source table fallback-stream)
                fallback-token-ids
                (set (map #(keyword (str "tok-" (:index %)))
                          (:tokens fallback-stream)))
                forms (:form-tree artifact)]
            (swap! artifacts assoc suffix artifact)
            (is (= (inc ordinal) @index-builds))
            (is (= reference-values (:parsed-semantic-values artifact)))
            (is (= reference-values (:parsed-values fallback-products)))
            (is (not-any? #(contains? % :token-id)
                          (:tokens fallback-stream)))
            (is (every? fallback-token-ids
                        (mapcat (juxt :open-token :close-token)
                                (:form-tree fallback-products))))
            (is (= :passed
                   (get-in artifact [:lexical-product-validation :status])))
            (is (= :stable
                   (get-in artifact [:incremental-reader-hashes :status])))
            (doseq [form forms
                    [ids-key hash-key]
                    [[:leading-trivia-token-ids :leading-trivia-hash]
                     [:trailing-trivia-token-ids :trailing-trivia-hash]]
                    :when (contains? form ids-key)]
              (is (= (reference-stage1-trivia-hash
                      (:token-stream artifact) (get form ids-key))
                     (get form hash-key))))
            (doseq [form (:form-tree fallback-products)
                    [ids-key hash-key]
                    [[:leading-trivia-token-ids :leading-trivia-hash]
                     [:trailing-trivia-token-ids :trailing-trivia-hash]]
                    :when (contains? form ids-key)]
              (is (= (reference-stage1-trivia-hash
                      (:tokens fallback-stream) (get form ids-key))
                     (get form hash-key))))))))
    (let [gravity (@artifacts ".gravity")
          qst (@artifacts ".qst")
          neutral-trivia
          (fn [artifact]
            (mapv #(-> %
                       (dissoc :source-path)
                       (update :span bootstrap/c2-path-neutral-span))
                  (:trivia-retention-records artifact)))]
      (is (= (get-in gravity [:source-unit-record :source-id])
             (get-in qst [:source-unit-record :source-id])))
      (is (= (bootstrap/c2-token-hash-input (:token-stream gravity))
             (bootstrap/c2-token-hash-input (:token-stream qst))))
      (is (= (bootstrap/c2-form-hash-input (:form-tree gravity))
             (bootstrap/c2-form-hash-input (:form-tree qst))))
      (is (= (bootstrap/c2-syntax-seed-hash-input
              (:syntax-seed-stream gravity))
             (bootstrap/c2-syntax-seed-hash-input
              (:syntax-seed-stream qst))))
      (is (= (:incremental-reader-hashes gravity)
             (:incremental-reader-hashes qst)))
      (is (= (:reader-product-integrity gravity)
             (:reader-product-integrity qst)))
      (is (= (:artifact-id gravity) (:artifact-id qst)))
      (is (= (mapv :token-id (:token-stream gravity))
             (mapv :token-id (:token-stream qst))))
      (is (= (mapv :form-id (:form-tree gravity))
             (mapv :form-id (:form-tree qst))))
      (is (= (mapv :syntax-id (:syntax-seed-stream gravity))
             (mapv :syntax-id (:syntax-seed-stream qst))))
      (is (= (mapv #(bootstrap/c2-path-neutral-span (:span %))
                   (:token-stream gravity))
             (mapv #(bootstrap/c2-path-neutral-span (:span %))
                   (:token-stream qst))))
      (is (= (mapv #(bootstrap/c2-path-neutral-span (:span %))
                   (:form-tree gravity))
             (mapv #(bootstrap/c2-path-neutral-span (:span %))
                   (:form-tree qst))))
      (is (= (neutral-trivia gravity) (neutral-trivia qst)))
      (is (not= (get-in gravity [:source-unit-record :path])
                (get-in qst [:source-unit-record :path])))
      (is (every? #(= (get-in gravity [:source-unit-record :path])
                      (get-in % [:span :source]))
                  (:token-stream gravity)))
      (is (every? #(= (get-in qst [:source-unit-record :path])
                      (get-in % [:span :source]))
                  (:token-stream qst))))))

(deftest c2-reader-token-index-large-source-makes-bounded-progress
  (let [definition-count 768
        source
        (str "(ns token.index.scale (:profile :hosted) (:target :jvm))\n"
             (apply str
                    (for [idx (range definition-count)]
                      (str "; retained source record " idx " λ🙂\n"
                           "(def value-" (format "%04d" idx)
                           " {:index " idx
                           " :label \"λ🙂\" :items [" idx " "
                           (inc idx) " " (+ idx 2)
                           "] :enabled true})\n"))))
        source-bytes (.getBytes source
                                java.nio.charset.StandardCharsets/UTF_8)
        token-index-var
        (ns-resolve 'gravity.bootstrap 'stage1-reader-token-index)
        original-token-index @token-index-var
        index-builds (atom 0)
        path "/token-index-scale/src/scale.gravity"
        artifact
        (with-redefs-fn
          {token-index-var
           (fn [tokens]
             (swap! index-builds inc)
             (original-token-index tokens))}
          #(bootstrap/compiler-c2-reader-source-artifact path source))
        forms-by-id (into {} (map (juxt :form-id identity)
                                  (:form-tree artifact)))
        last-root (forms-by-id (last (:top-level-form-ids artifact)))]
    (is (< 50000 (alength source-bytes) 150000))
    (is (zero? @index-builds))
    (is (= (inc definition-count)
           (count (:top-level-form-ids artifact))))
    (is (> (count (:token-stream artifact)) 10000))
    (is (> (count (:form-tree artifact)) 8000))
    (is (= (str "(def value-" (format "%04d" (dec definition-count)))
           (subs (:raw last-root) 0 15)))
    (is (= (dec (alength source-bytes))
           (get-in last-root [:span :byte-end])))
    (is (= :passed
           (get-in artifact [:lexical-product-validation :status])))
    (is (= :stable
           (get-in artifact [:incremental-reader-hashes :status])))
    (is (re-matches #"sha256:[0-9a-f]{64}" (:artifact-id artifact)))))

(deftest c2-reader-token-index-preserves-hostile-and-malformed-diagnostics
  (let [token-index-var
        (ns-resolve 'gravity.bootstrap 'stage1-reader-token-index)
        original-token-index @token-index-var
        cases [{:name :odd-map
                :source "; retained trivia\n{:a 1 :b}"
                :expected {:id "C2-MAP"
                           :remapped-from "L1-MAP-ARITY"
                           :reader-engine-diagnostic "STAGE1READER005"}
                :index-builds 0}
               {:name :unexpected-close
                :source "]"
                :expected {:id "C2-DELIMITER"
                           :remapped-from "L1-DELIMITER"
                           :reader-engine-diagnostic "STAGE1READER001"}
                :index-builds 0}
               {:name :malformed-number
                :source "1e2e3"
                :expected {:id "C2-NUMERIC"
                           :remapped-from "L1-NUMERIC"
                           :reader-engine-diagnostic "STAGE1READER007"}
                :index-builds 0}]]
    (doseq [{:keys [name source expected index-builds]} cases]
      (let [diagnostics (atom {})
            project-root "/token-index-hostile"
            project-context
            {:project-root-id
             (bootstrap/reader-canonical-hash
              {:project :token-index-hostile :case name})
             :project-root-path project-root
             :project-relative-path
             (str "src/" (clojure.core/name name))}]
        (doseq [suffix [".gravity" ".qst"]]
          (let [path (str project-root "/src/" (clojure.core/name name)
                          suffix)
                builds (atom 0)
                diagnostic
                (with-redefs-fn
                  {token-index-var
                   (fn [tokens]
                     (swap! builds inc)
                     (original-token-index tokens))}
                  #(diagnostic-data
                    (fn []
                      (bootstrap/compiler-c2-reader-source-artifact
                       path source project-context))))
                projection
                (select-keys diagnostic
                             (keys expected))]
            (swap! diagnostics assoc suffix diagnostic)
            (is (= expected projection) (str name suffix))
            (is (= index-builds @builds) (str name suffix))
            (is (= :error (:severity diagnostic)))
            (is (= :read-source (:stage diagnostic)))
            (is (= :c2-reader (:diagnostic-family diagnostic)))
            (is (= path (get-in diagnostic [:source-span :source])))
            (is (= (:source-span diagnostic)
                   (get-in diagnostic [:primary :span])))
            (is (re-matches #"sha256:[0-9a-f]{64}"
                            (:diagnostic-id diagnostic)))))
        (let [gravity (@diagnostics ".gravity")
              qst (@diagnostics ".qst")]
          (is (= (:source-id gravity) (:source-id qst))
              (str name " source identity parity"))
          (is (= (:diagnostic-id gravity) (:diagnostic-id qst))
              (str name " diagnostic identity parity"))
          (is (= (dissoc (:source-span gravity) :source)
                 (dissoc (:source-span qst) :source))
              (str name " diagnostic span parity"))
          (is (not= (get-in gravity [:source-span :source])
                    (get-in qst [:source-span :source])))
          (is (= (select-keys gravity
                            [:id :severity :stage :token-id :form-id
                             :raw-spelling :facts :remapped-from
                             :reader-engine-diagnostic :reader-state])
                 (select-keys qst
                            [:id :severity :stage :token-id :form-id
                             :raw-spelling :facts :remapped-from
                             :reader-engine-diagnostic :reader-state]))
              (str name " extension parity")))))))

(deftest stage1-reader-character-stream-uses-unicode-scalars-and-exact-bytes
  (doseq [suffix [".gravity" ".qst"]
          source ["🙂x" "a🙂b" "x🙂" "🙂x \"a🙂b\" x🙂"]]
    (let [path (str "/unicode-probe/source" suffix)
          stream (bootstrap/stage1-reader-character-stream path source)
          characters (:characters stream)
          source-bytes (.getBytes source java.nio.charset.StandardCharsets/UTF_8)]
      (is (= (.codePointCount source 0 (.length source))
             (:character-count stream)))
      (is (= (.length source) (:utf16-unit-count stream)))
      (is (= (range (count characters)) (map :index characters)))
      (is (every? #(= (:raw %)
                      (bootstrap/c2-utf8-slice
                       source-bytes
                       (get-in % [:span :byte-start])
                       (get-in % [:span :byte-end])))
                  characters))
      (is (every? #(= (.codePointAt ^String (:raw %) 0) (:codepoint %))
                  characters))))
  (doseq [suffix [".gravity" ".qst"]]
    (let [stream (bootstrap/stage1-reader-character-stream
                  (str "x" suffix) "🙂x")
          [emoji x] (:characters stream)]
      (is (= ["🙂" "x"] (mapv :raw (:characters stream))))
      (is (= 128578 (:codepoint emoji)))
      (is (= [0 4 1 2]
             [(get-in emoji [:span :byte-start])
              (get-in emoji [:span :byte-end])
              (get-in emoji [:span :start :column])
              (get-in emoji [:span :end :column])]))
      (is (= [4 5 2 3]
             [(get-in x [:span :byte-start])
              (get-in x [:span :byte-end])
              (get-in x [:span :start :column])
              (get-in x [:span :end :column])]))))
  (doseq [suffix [".gravity" ".qst"]]
    (with-temp-source
      suffix "🙂x \"a🙂b\" x🙂\n"
      (fn [path]
        (let [classifier
              (bootstrap/stage1-reader-token-classifier-pipeline-file-artifact
               path)
              realizer
              (bootstrap/stage1-reader-token-realizer-pipeline-file-artifact
               path)
              automaton
              (bootstrap/stage1-reader-token-automaton-pipeline-file-artifact
               path)
              executor
              (bootstrap/stage1-reader-executor-pipeline-file-artifact path)
              c2 (bootstrap/compiler-c2-reader-file-artifact path)
              expected ['🙂x "a🙂b" 'x🙂]]
          (is (= expected
                 (mapv :form (:stage1-reader-records classifier))))
          (is (= expected
                 (mapv :form (:stage1-reader-records realizer))))
          (is (= expected
                 (mapv :form (:stage1-reader-records automaton))))
          (is (= expected
                 (mapv :form (:stage1-reader-records executor))))
          (is (= expected (:parsed-semantic-values c2)))
          (is (every? #(= :unicode-scalar
                          (get-in % [:span :start :column-unit]))
                      (:token-stream c2))))))))

(deftest c2-reader-treats-cr-lf-and-crlf-as-line-terminators
  (doseq [suffix [".gravity" ".qst"]
          newline ["\r" "\n" "\r\n"]]
    (let [source (str "; c" newline "[🙂 1]" newline)]
      (with-temp-source
        suffix source
        (fn [path]
          (let [retained
                (bootstrap/c2-reader-products
                 path source bootstrap/standard-reader-options)
                ignored
                (bootstrap/c2-reader-products
                 path source
                 (assoc bootstrap/standard-reader-options
                        :retain-comments false))
                compiler (bootstrap/compiler-c2-reader-file-artifact path)
                p15 (bootstrap/p15-s23-source-syntax-c2-artifact path source)
                tokens (:token-stream retained)
                source-bytes (.getBytes source
                                        java.nio.charset.StandardCharsets/UTF_8)
                comment (first (filter #(= :comment (:kind %)) tokens))
                newline-token
                (first (filter #(and (= :whitespace (:kind %))
                                     (= newline (:raw %)))
                               tokens))
                vector-open (first (filter #(= :vector-open (:kind %))
                                           tokens))
                skipped
                (bootstrap/p15-s23-front-end-skip-comment
                 (bootstrap/p15-s23-front-end-state path source))]
            (is (= [['🙂 1N]] (:parsed-values retained)))
            (is (= (:parsed-values retained) (:parsed-values ignored)))
            (is (= (:parsed-values retained)
                   (:parsed-semantic-values compiler)))
            (is (= (:parsed-values retained)
                   (:parsed-semantic-values p15)))
            (is (= "; c" (:raw comment)))
            (is (= newline (:raw newline-token)))
            (is (= [2 1]
                   [(get-in vector-open [:span :start :line])
                    (get-in vector-open [:span :start :column])]))
            (is (= :unicode-scalar
                   (get-in vector-open [:span :start :column-unit])))
            (is (= \[ (bootstrap/p15-s23-front-end-current-char skipped)))
            (is (= [2 1] [(:line skipped) (:column skipped)]))
            (is (every? #(= (:raw %)
                            (bootstrap/c2-utf8-slice
                             source-bytes
                             (get-in % [:span :byte-start])
                             (get-in % [:span :byte-end])))
                        tokens))
            (is (not-any? :trivia? (:token-stream ignored)))))))))

(deftest p15-stage2-front-end-preserves-crlf-inside-strings
  (doseq [suffix [".gravity" ".qst"]
          newline ["\r" "\n" "\r\n"]]
    (let [path (str "/p15-line-probe/source" suffix)
          source (str "\"a" newline "b\"")
          [record end-state]
          (bootstrap/p15-s23-front-end-read-form
           path (bootstrap/p15-s23-front-end-state path source) 0)]
      (is (= (str "a" newline "b") (:form record)))
      (is (= (count source) (:idx end-state)))
      (is (= [2 3] [(:line end-state) (:column end-state)]))
      (is (= (alength (.getBytes source
                                 java.nio.charset.StandardCharsets/UTF_8))
             (get-in record [:span :byte-end]))))))

(deftest c2-reader-form-graph-validation-rejects-adversarial-mutations
  (let [source "[{:a [1 2] :b (3 4)} #{:x :y}]"
        path "/graph-validation/src/tree.gravity"
        artifact (bootstrap/compiler-c2-reader-source-artifact path source)
        forms (:form-tree artifact)
        roots (:top-level-form-ids artifact)
        forms-by-id (into {} (map (juxt :form-id identity) forms))
        root-id (first roots)
        root (forms-by-id root-id)
        map-form (first (filter #(= :map (:collection-kind %)) forms))
        nested-parent
        (first (filter #(and (:parent-form-id %) (seq (:children %))) forms))
        target-id (first (:children root))
        nested-target-id (first (:children nested-parent))
        child-frequencies (frequencies (mapcat :children forms))
        replace-form
        (fn [form-tree form-id update-fn]
          (mapv #(if (= form-id (:form-id %)) (update-fn %) %) form-tree))
        mutations
        [{:name :bad-parent
          :forms (replace-form forms target-id
                               #(assoc % :parent-form-id :missing-parent))}
         {:name :orphan
          :forms (conj forms
                       (assoc (forms-by-id target-id)
                              :form-id :orphan-form
                              :parent-form-id nil))}
         {:name :cycle
          :forms (replace-form forms root-id
                               #(update % :children conj root-id))}
         {:name :duplicate-child
          :forms (replace-form forms root-id
                               #(update % :children conj target-id))}
         {:name :out-of-order-child
          :forms (replace-form forms root-id
                               #(update % :children (comp vec reverse)))}
         {:name :span-escape
          :forms
          (replace-form
           forms nested-target-id
           #(assoc-in % [:span :byte-end]
                      (inc (get-in nested-parent [:span :byte-end]))))}
         {:name :odd-map
          :forms (replace-form forms (:form-id map-form)
                               #(update % :children pop))}]]
    (is (= :passed (get-in artifact [:lexical-product-validation :status])))
    (is (true? (get-in artifact [:lexical-product-validation :graph-valid?])))
    (is (every? #(nil? (:parent-form-id (forms-by-id %))) roots))
    (is (every? #(if (contains? (set roots) (:form-id %))
                   (zero? (get child-frequencies (:form-id %) 0))
                   (= 1 (get child-frequencies (:form-id %) 0)))
                forms))
    (doseq [{:keys [name forms]} mutations]
      (let [validation
            (bootstrap/c2-lexical-product-validation
             source (:token-stream artifact) forms roots)
            mutated (assoc artifact
                           :form-tree forms
                           :lexical-product-validation validation)
            proof (bootstrap/c2-reader-capability-proof mutated)
            diagnostic
            (diagnostic-data #(bootstrap/c2-reader-validate! path mutated))]
        (is (= :failed (:status validation)) (str name))
        (is (false? (:graph-valid? validation)) (str name))
        (is (true? (:lexical-token-stream? proof)) (str name))
        (is (false? (:nested-form-tree? proof)) (str name))
        (is (= "C2-HASH" (:id diagnostic)) (str name))
        (is (= :c2-reader (:diagnostic-family diagnostic)) (str name))
        (is (= :read-source (:stage diagnostic)) (str name))))))

(deftest c2-reader-trivia-options-control-genuine-product-hashes
  (let [base "(ns hash.reader (:profile :hosted))\n; aa\n(def value [1 2])\n"
        changed-comment (str/replace base "; aa" "; bb")
        changed-space (str/replace base "(def value" "(def  value")
        context {:project-root-id
                 (bootstrap/reader-canonical-hash {:project :reader-hash})
                 :project-root-path "/logical-project"
                 :project-relative-path "src/hash.gravity"}
        build (fn [source options]
                (let [products (bootstrap/c2-reader-products
                                "/logical-project/src/hash.gravity"
                                source options context)]
                  (assoc products
                         :hashes
                         (bootstrap/c2-incremental-hashes
                          (:source-unit products)
                          (:token-stream products)
                          (:form-tree products)
                          [] [] []))))
        retained (mapv #(build % bootstrap/standard-reader-options)
                       [base changed-comment changed-space])
        ignored-options (assoc bootstrap/standard-reader-options
                               :retain-comments false)
        ignored (mapv #(build % ignored-options)
                      [base changed-comment changed-space])]
    (is (apply = (map :parsed-values retained)))
    (is (apply = (map :parsed-values ignored)))
    (is (= (mapv :parsed-values retained)
           (mapv :parsed-values ignored)))
    (is (every? #(some (comp #{:comment} :kind) (:token-stream %))
                retained))
    (is (every? #(not-any? :trivia? (:token-stream %)) ignored))
    (is (= 3 (count (set (map #(get-in % [:hashes :token-stream])
                              retained)))))
    (is (= 3 (count (set (map #(get-in % [:hashes :form-tree])
                              retained)))))
    (is (= 3 (count (set (map #(get-in % [:hashes :token-stream])
                              ignored)))))
    (is (= 1 (count (set (map #(get-in % [:hashes :form-tree])
                              ignored)))))
    (is (not= (get-in (first retained) [:hashes :token-stream])
              (get-in (first ignored) [:hashes :token-stream])))
    (is (not= (get-in (first retained) [:hashes :form-tree])
              (get-in (first ignored) [:hashes :form-tree])))
    (is (every? #(true? (get-in % [:hashes
                                    :retained-trivia-affects-form-tree?]))
                retained))
    (is (every? #(false? (get-in % [:hashes
                                     :retained-trivia-affects-form-tree?]))
                ignored))
    (let [root-id (bootstrap/reader-canonical-hash
                   {:project :same-reader-checkout})
          context-a {:project-root-id root-id
                     :project-root-path "/checkout-a"
                     :project-relative-path "src/hash.gravity"}
          context-b {:project-root-id root-id
                     :project-root-path "/checkout-b"
                     :project-relative-path "src/hash.gravity"}
          products-a (bootstrap/c2-reader-products
                      "/checkout-a/src/hash.gravity" base
                      bootstrap/standard-reader-options context-a)
          products-b (bootstrap/c2-reader-products
                      "/checkout-b/src/hash.gravity" base
                      bootstrap/standard-reader-options context-b)
          hashes (fn [products]
                   (let [source-path (get-in products [:source-unit :path])
                         module-context
                         (bootstrap/reader-module-context
                          (:parsed-values products))
                         syntax-seeds
                         (bootstrap/c2-syntax-seed-stream
                          source-path products module-context)]
                     {:syntax-seeds syntax-seeds
                      :hashes
                      (bootstrap/c2-incremental-hashes
                       (:source-unit products)
                       (:token-stream products)
                       (:form-tree products)
                       syntax-seeds [] [])}))
          hash-products-a (hashes products-a)
          hash-products-b (hashes products-b)
          hashes-a (:hashes hash-products-a)
          hashes-b (:hashes hash-products-b)
          diagnostic (fn [path products]
                       (let [source-unit (:source-unit products)
                             token (first (:token-stream products))]
                         (diagnostic-data
                          #(bootstrap/c2-reader-fail!
                            "C2-HASH" path
                            {:source-id (:source-id source-unit)
                             :source-span (:span token)
                             :token-id (:token-id token)
                             :raw (:raw token)
                             :reader-options (:reader-options source-unit)}
                            {:facts {:reason :portable-identity-probe}}))))
          diagnostic-a (diagnostic "/checkout-a/src/hash.gravity" products-a)
          diagnostic-b (diagnostic "/checkout-b/src/hash.gravity" products-b)]
      (is (= (get-in products-a [:source-unit :source-id])
             (get-in products-b [:source-unit :source-id])))
      (is (not= (get-in products-a [:source-unit :path])
                (get-in products-b [:source-unit :path])))
      (is (= hashes-a hashes-b))
      (is (not= (get-in products-a [:token-stream 0 :source-path])
                (get-in products-b [:token-stream 0 :source-path])))
      (is (not= (get-in products-a [:form-tree 0 :span :source])
                (get-in products-b [:form-tree 0 :span :source])))
      (is (not= (get-in hash-products-a
                        [:syntax-seeds 0 :span :source])
                (get-in hash-products-b
                        [:syntax-seeds 0 :span :source])))
      (is (= (:diagnostic-id diagnostic-a)
             (:diagnostic-id diagnostic-b)))
      (is (not= (get-in diagnostic-a [:source-span :source])
                (get-in diagnostic-b [:source-span :source]))))))

(deftest c2-reader-rejects-hostile-lexical-inputs-with-stable-c15-payloads
  (let [cases [{:name :unexpected-close :source "]"
                :id "C2-DELIMITER" :token-id? true
                :remapped-from "L1-DELIMITER"
                :engine-diagnostic "STAGE1READER001"}
               {:name :mismatch :source "([)]"
                :id "C2-DELIMITER" :token-id? true
                :byte-start 2 :byte-end 3
                :remapped-from "L1-DELIMITER"
                :engine-diagnostic "STAGE1READER001"}
               {:name :unclosed :source "("
                :id "C2-DELIMITER" :token-id? true
                :remapped-from "L1-DELIMITER"
                :engine-diagnostic "STAGE1READER002"}
               {:name :string :source "\"bad\\q\""
                :id "C2-STRING" :token-id? true
                :remapped-from "L1-STRING"
                :engine-diagnostic "STAGE1READER003"}
               {:name :character :source "\\not-a-character"
                :id "C2-STRING" :token-id? true
                :remapped-from "L1-STRING"
                :engine-diagnostic "STAGE1READER003"}
               {:name :odd-map :source "{:a 1 :b}"
                :id "C2-MAP" :token-id? true
                :remapped-from "L1-MAP-ARITY"
                :engine-diagnostic "STAGE1READER005"}
               {:name :duplicate-set :source "#{:dup :dup}"
                :id "C2-SET" :token-id? true :related? true
                :remapped-from "L1-SET"}
               {:name :duplicate-composite-set :source "#{[1] [1]}"
                :id "C2-SET" :token-id? true :related? true
                :remapped-from "L1-SET"}
               {:name :duplicate-nested-set
                :source "#{{:a [1]} {:a [1]}}"
                :id "C2-SET" :token-id? true :related? true
                :remapped-from "L1-SET"}
               {:name :duplicate-quoted-set :source "#{'x 'x}"
                :id "C2-SET" :token-id? true :related? true
                :remapped-from "L1-SET"}
               {:name :duplicate-metadata-set :source "#{^:a x ^:a x}"
                :id "C2-SET" :token-id? true :related? true
                :remapped-from "L1-SET"}
               {:name :duplicate-deref-set :source "#{@x @x}"
                :id "C2-SET" :token-id? true :related? true
                :remapped-from "L1-SET"}]]
    (doseq [{:keys [name source id token-id? related? byte-start byte-end
                    remapped-from engine-diagnostic]}
            cases]
      (let [diagnostics (atom {})]
        (doseq [suffix [".gravity" ".qst"]]
          (with-temp-source
            suffix source
            (fn [path]
              (let [diagnostic
                    (diagnostic-data
                     #(bootstrap/compiler-c2-reader-file-artifact path))
                    repeated
                    (diagnostic-data
                     #(bootstrap/compiler-c2-reader-file-artifact path))]
                (swap! diagnostics assoc suffix diagnostic)
                (is (= id (:id diagnostic)) (str name suffix))
                (is (= :error (:severity diagnostic)))
                (is (= :read-source (:stage diagnostic)))
                (is (= :c2-reader (:diagnostic-family diagnostic)))
                (is (= path (get-in diagnostic [:source-span :source])))
                (is (= (:source-span diagnostic)
                       (get-in diagnostic [:primary :span])))
                (is (= (:source-id diagnostic)
                       (get-in diagnostic [:primary :artifact])))
                (is (re-matches #"sha256:[0-9a-f]{64}"
                                (:source-id diagnostic)))
                (is (re-matches #"sha256:[0-9a-f]{64}"
                                (:diagnostic-id diagnostic)))
                (is (vector? (:related diagnostic)))
                (is (seq (:origin-chain diagnostic)))
                (is (contains? diagnostic :profile))
                (is (contains? diagnostic :target))
                (is (map? (:facts diagnostic)))
                (is (string? (:remediation diagnostic)))
                (is (seq (:remediation-records diagnostic)))
                (is (= bootstrap/standard-reader-options
                       (:reader-options diagnostic)))
                (is (string? (:raw-spelling diagnostic)))
                (is (= remapped-from (:remapped-from diagnostic)))
                (is (= engine-diagnostic
                       (:reader-engine-diagnostic diagnostic)))
                (is (= :gravity/reader-state
                       (get-in diagnostic [:reader-state :artifact])))
                (is (contains? #{:lexical-tokenization
                                 :recursive-form-building}
                               (get-in diagnostic [:reader-state :stage])))
                (is (integer? (get-in diagnostic
                                      [:reader-state :byte-offset])))
                (when token-id?
                  (is (keyword? (:token-id diagnostic))))
                (when related?
                  (is (seq (:related diagnostic))))
                (when byte-start
                  (is (= byte-start
                         (get-in diagnostic [:source-span :byte-start]))))
                (when byte-end
                  (is (= byte-end
                         (get-in diagnostic [:source-span :byte-end]))))
                (is (= (select-keys diagnostic
                                    [:id :severity :stage :token-id :form-id
                                     :raw-spelling :facts :remapped-from
                                     :reader-engine-diagnostic :reader-state])
                       (select-keys repeated
                                    [:id :severity :stage :token-id :form-id
                                     :raw-spelling :facts :remapped-from
                                     :reader-engine-diagnostic
                                     :reader-state])))))))
        (is (= (select-keys (@diagnostics ".gravity")
                            [:id :severity :stage :token-id :form-id
                             :raw-spelling :facts :remapped-from
                             :reader-engine-diagnostic :reader-state])
               (select-keys (@diagnostics ".qst")
                            [:id :severity :stage :token-id :form-id
                             :raw-spelling :facts :remapped-from
                             :reader-engine-diagnostic :reader-state])))))))

