          (is (= "C2-NUMERIC" (:id c2) (:id p15)))
          (is (= "L1-NUMERIC" (:remapped-from c2)))
          (is (= "STAGE1READER007" (:reader-engine-diagnostic c2)))
          (is (nil? (get-in c2 [:facts :normative-c2-mapping])))
