(deftest rejected-fixtures-produce-stable-diagnostics
  (testing "malformed source is a reader error"
    (is (= "L1-DELIMITER"
           (diagnostic-id #(bootstrap/compile-file (fixture "rejected/malformed.gravity"))))))
  (testing "odd map literals are reader errors"
    (is (= "L1-MAP-ARITY"
           (diagnostic-id #(bootstrap/read-file-artifact (fixture "rejected/map-arity.gravity"))))))
  (testing "invalid string escapes are reader errors"
    (is (= "L1-STRING"
           (diagnostic-id #(bootstrap/read-file-artifact (fixture "rejected/invalid-string.gravity"))))))
  (testing "invalid namespace syntax is a reader error"
    (is (= "L1-NS-SHAPE"
           (diagnostic-id #(bootstrap/read-file-artifact (fixture "rejected/invalid-ns-shape.gravity"))))))
  (testing "unregistered reader extensions are reader errors"
    (is (= "L1-READER-EXTENSION"
           (diagnostic-id #(bootstrap/read-file-artifact (fixture "rejected/reader-extension.gravity"))))))
  (testing "malformed metadata is a reader error"
    (is (= "L1-METADATA"
           (diagnostic-id #(bootstrap/read-file-artifact (fixture "rejected/metadata.gravity"))))))
  (testing "unsupported profile is rejected"
    (is (= "P1-PROFILE-UNSUPPORTED"
           (diagnostic-id #(bootstrap/compile-file (fixture "rejected/unknown-profile.gravity"))))))
  (testing "host reflection in kernel profile is rejected"
    (is (= "P7-HOST-REFLECTION"
           (diagnostic-id #(bootstrap/compile-file (fixture "rejected/kernel-reflection.gravity"))))))
  (testing "println requires declared io effect"
    (is (= "L6-EFFECT-UNDECLARED"
           (diagnostic-id #(bootstrap/compile-file (fixture "rejected/missing-effect.gravity"))))))
  (testing "println requires stdout capability"
    (is (= "L3-CAPABILITY-MISSING"
           (diagnostic-id #(bootstrap/compile-file (fixture "rejected/missing-capability.gravity"))))))
  (testing "stage0 rejects unknown executable forms"
    (is (= "L2-UNKNOWN-CORE-FORM"
           (diagnostic-id #(bootstrap/run-file (fixture "rejected/unsupported-form.gravity"))))))
  (testing "multiple active profiles are rejected"
    (is (= "L3-PROFILE-MULTIPLE"
           (diagnostic-id #(bootstrap/module-file-artifact (fixture "rejected/multiple-profile.gravity"))))))
  (testing "unknown aliases are rejected"
    (is (= "L3-UNKNOWN-ALIAS"
           (diagnostic-id #(bootstrap/module-file-artifact (fixture "rejected/unknown-alias.gravity"))))))
  (testing "ambiguous aliases are rejected"
    (is (= "L3-AMBIGUOUS-NAME"
           (diagnostic-id #(bootstrap/module-file-artifact (fixture "rejected/ambiguous-alias.gravity"))))))
  (testing "private imports are rejected"
    (is (= "L3-PRIVATE-IMPORT"
           (diagnostic-id #(bootstrap/module-file-artifact (fixture "rejected/private-import.gravity"))))))
  (testing "cross-profile imports without boundary are rejected"
    (is (= "L3-CROSS-PROFILE"
           (diagnostic-id #(bootstrap/module-file-artifact (fixture "rejected/cross-profile.gravity"))))))
  (testing "namespace effect widening is rejected"
    (is (= "L3-EFFECT-WIDEN"
           (diagnostic-id #(bootstrap/module-file-artifact (fixture "rejected/effect-widen.gravity"))))))
  (testing "module capability gaps are rejected"
    (is (= "L3-CAPABILITY-MISSING"
           (diagnostic-id #(bootstrap/module-file-artifact (fixture "rejected/module-missing-capability.gravity"))))))
  (testing "unknown reserved core forms are rejected"
    (is (= "L2-UNKNOWN-CORE-FORM"
           (diagnostic-id #(bootstrap/core-file-artifact (fixture "rejected/core-unknown-form.gravity"))))))
  (testing "evaluation order rewrites are rejected"
    (is (= "L2-EVAL-ORDER"
           (diagnostic-id #(bootstrap/core-file-artifact (fixture "rejected/eval-order.gravity"))))))
  (testing "recur without compatible target is rejected"
    (is (= "L2-RECUR-TARGET"
           (diagnostic-id #(bootstrap/core-file-artifact (fixture "rejected/recur-target.gravity"))))))
  (testing "illegal set! targets are rejected"
    (is (= "L2-SET-ILLEGAL"
           (diagnostic-id #(bootstrap/core-file-artifact (fixture "rejected/set-illegal.gravity"))))))
  (testing "throw without effect is rejected"
    (is (= "L2-THROW-ILLEGAL"
           (diagnostic-id #(bootstrap/core-file-artifact (fixture "rejected/throw-illegal.gravity"))))))
  (testing "host semantics leakage is rejected"
    (is (= "L2-HOST-SEMANTICS"
           (diagnostic-id #(bootstrap/core-file-artifact (fixture "rejected/host-semantics.gravity"))))))
  (testing "surface forms without lowering are rejected"
    (is (= "L2-LOWERING-GAP"
           (diagnostic-id #(bootstrap/core-file-artifact (fixture "rejected/lowering-gap.gravity"))))))
  (testing "macros must return syntax"
    (is (= "L4-MACRO-NOT-SYNTAX"
           (diagnostic-id #(bootstrap/macro-file-artifact (fixture "rejected/macro-not-syntax.gravity"))))))
  (testing "macro build effects require declaration and grant"
    (is (= "L4-BUILD-EFFECT"
           (diagnostic-id #(bootstrap/macro-file-artifact (fixture "rejected/macro-build-effect.gravity"))))))
  (testing "recursive macros hit the expansion limit"
    (is (= "L4-EXPANSION-DEPTH"
           (diagnostic-id #(bootstrap/macro-file-artifact (fixture "rejected/macro-depth.gravity"))))))
  (testing "macro output must obey the caller profile"
    (is (= "L4-GENERATED-PROFILE"
           (diagnostic-id #(bootstrap/macro-file-artifact (fixture "rejected/macro-generated-profile.gravity"))))))
  (testing "unsafe macro output requires explicit policy"
    (is (= "L4-GENERATED-UNSAFE"
           (diagnostic-id #(bootstrap/macro-file-artifact (fixture "rejected/macro-generated-unsafe.gravity"))))))
  (testing "macro hygiene rejects accidental capture"
    (is (= "L4-HYGIENE-CAPTURE"
           (diagnostic-id #(bootstrap/macro-file-artifact (fixture "rejected/macro-hygiene-capture.gravity"))))))
  (testing "macro expansion requires generated provenance"
    (is (= "L4-PROVENANCE-MISSING"
           (diagnostic-id #(bootstrap/macro-file-artifact (fixture "rejected/macro-provenance.gravity"))))))
