                                "--version")
        core-check (run-bin bootstrap/p18-t05-release-binary-path
                            "check" "examples/core-app.gravity")
        core-run (run-bin bootstrap/p18-t05-release-binary-path
                          "run" "examples/core-app.gravity")
        core-compile (run-bin bootstrap/p18-t05-release-binary-path
                              "compile" "examples/core-app.gravity"
                              "-o" "target/phase-18/seedless/test-core-app")
        core-exec (run-bin "target/phase-18/seedless/test-core-app")
        inspect-result (run-bin bootstrap/p18-t05-release-binary-path
                                "inspect"
                                "target/phase-18/seedless/test-core-app.gravity-artifact.edn")
        release-proof-result
        (run-bin bootstrap/p18-t05-release-binary-path
                 "p18-t05-seedless-release-boundary")
        invalid-compile (run-bin bootstrap/p18-t05-release-binary-path
                                 "compile"
                                 (fixture "rejected/core-app-backend-release.gravity")
                                 "-o"
                                 "target/phase-18/seedless/test-invalid")]
    (is (= :gravity/p18-t05-seedless-release-boundary-proof
           (:kind artifact)))
    (is (= "P18-T05" (:task artifact)))
    (is (= :incomplete (:status artifact)))
    (is (re-find #"^sha256:" (:artifact-id artifact)))
    (is (= :incomplete (:status proof)))
    (is (true? (:boundary-diagnostics-covered? proof)))
    (is (false? (:all-required-seed-boundary-facts-false? proof)))
    (is (false? (:gravity-binary-clojure-seed-boundary? proof)))
    (is (true? (:compiler-path-clojure-seed-boundary? proof)))
    (is (true? (:runtime-path-clojure-seed-boundary? proof)))
    (is (true? (:release-compiler-path-clojure-seed-boundary? proof)))
    (is (true? (:accepted-fixtures-covered? proof)))
    (is (true? (:accepted-check-run-compile-survived? proof)))
    (is (false? (:artifact-inspection-seedless? proof)))
    (is (false? (:release-proof-command-seedless? proof)))
    (is (true? (:rejected-command-fixtures-covered? proof)))
    (is (true? (:rejected-boundary-fixtures-covered? proof)))
    (is (true? (:diagnostics-covered? proof)))
    (is (true? (:bootstrap-recovery-explicit? proof)))
    (is (true? (:bootstrap-excluded-from-public-release-boundary? proof)))
    (is (false? (:seedless-release-boundary-eligible? proof)))
    (is (false? (:final-release-eligible? proof)))
    (is (= :p15-s23-final-seed-retirement
           (:next-required-capability proof)))
    (is (contains? (set (map :diagnostic (:diagnostics artifact)))
                   "P18T05001"))
    (is (contains? (set (map :diagnostic (:diagnostics artifact)))
                   "P18T05003"))
    (is (= false (:clojure-seed-boundary?
                  (get components :gravity-binary))))
    (is (= true (:clojure-seed-boundary?
                  (get components :compiler-path))))
    (is (= true (:clojure-seed-boundary?
                  (get components :runtime-path))))
    (is (= true (:clojure-seed-boundary?
                  (get components :release-compiler-path))))
    (is (= false
           (get-in boundary
                   [:seed-boundary-facts
                    :binary-clojure-seed-boundary?])))
    (is (= true
           (get-in boundary
                   [:seed-boundary-facts
                    :compiler-path-clojure-seed-boundary?])))
    (is (= true
           (get-in boundary
                   [:seed-boundary-facts
                    :runtime-path-clojure-seed-boundary?])))
    (is (= true
           (get-in boundary
                   [:seed-boundary-facts
                    :release-compiler-clojure-seed-boundary?])))
    (is (= false
           (get-in boundary
                   [:bootstrap-recovery-boundary
                    :included-in-public-release-boundary?])))
    (is (= false
           (get-in boundary
                   [:bootstrap-hosted-command-boundary
                    :included-in-public-release-boundary?])))
    (is (.canExecute (java.io.File. bootstrap/p18-t05-release-binary-path)))
    (is (= "core-app\ngravity:19:2\n(:ok 19)\n"
           (:expected-stdout core-record)))
    (is (= "core-app\ngravity:19:2\n(:ok 19)\n"
           (get-in core-record [:executable-result :out])))
    (is (every? true? (map :matches-expected?
                           (:accepted-boundary-proofs artifact))))
    (is (every? true? (map :matches-expected?
                           (:rejected-command-proofs artifact))))
    (is (every? true? (map :matches-expected?
                           (:rejected-boundary-fixtures artifact))))
    (is (= #{"P18T05001" "P18T05002" "P18T05003"
             "P18T05004" "P18T05005"}
           (set (map :expected-diagnostic
                     (:rejected-boundary-fixtures artifact)))))
    (is (.isFile (java.io.File.
                  "docs/artifacts/phase-18/seedless/p18-t05-seedless-release-boundary-proof.edn")))
    (is (.isFile (java.io.File.
                  "docs/artifacts/phase-18/seedless/p18-t05-release-boundary.edn")))
    (is (.isFile (java.io.File.
                  "docs/artifacts/phase-18/seedless/p18-t05-provenance-attestation.edn")))
    (is (.isFile (java.io.File.
                  "docs/artifacts/phase-18/seedless/p18-t05-bootstrap-audit-record.edn")))
    (is (zero? (:exit version-result)))
    (is (str/includes? (:out version-result)
                       ":clojure-seed-boundary? true"))
    (is (zero? (:exit core-check)))
    (is (str/includes? (:out core-check)
                       "gravity seedless check passed: core.app"))
    (is (zero? (:exit core-run)))
    (is (= "core-app\ngravity:19:2\n(:ok 19)\n" (:out core-run)))
    (is (zero? (:exit core-compile)))
    (is (str/includes? (:out core-compile)
                       ":gravity/p18-t05-seedless-executable-artifact"))
    (is (zero? (:exit core-exec)))
    (is (= "core-app\ngravity:19:2\n(:ok 19)\n" (:out core-exec)))
    (is (zero? (:exit inspect-result)))
    (is (str/includes? (:out inspect-result)
                       ":clojure-seed-boundary? true"))
    (is (zero? (:exit release-proof-result)))
    (is (str/includes? (:out release-proof-result)
                       ":component :gravity-binary"))
    (is (str/includes? (:out release-proof-result)
                       ":clojure-seed-boundary? true"))
    (is (= 1 (:exit invalid-compile)))
    (is (str/includes? (:err invalid-compile) "B13-RELEASE"))))

