(deftest p18-final-release-proves-reproducibility-provenance-sbom-signing-and-governance
  (let [artifact (bootstrap/p18-t06-write-final-release-artifacts!)
        proof (:capability-based-proof artifact)
        boundary (:release-boundary-record artifact)
        p15-proof (:p15-final-seed-retirement-proof artifact)
        diagnostics (set (map :diagnostic (:diagnostics artifact)))
        version-result (run-bin "bin/gravity" "--version")
        seedless-assert (run-bin "bin/gravity" "--assert-seedless-release")
        release-test-result (run-bin bootstrap/p18-t06-release-binary-path
                                     "test")
        release-test-artifact (when (zero? (:exit release-test-result))
                                (edn/read-string (:out release-test-result)))
        release-test-overclaim (run-bin bootstrap/p18-t06-release-binary-path
                                        "test" "--full")]
    (is (= :gravity/p18-t06-final-release-proof (:kind artifact)))
    (is (= "P18-T06" (:task artifact)))
    (is (= :incomplete (:status artifact)))
    (is (false? (:final-release? artifact)))
    (is (false? (:seedless-release? artifact)))
    (is (true? (:clojure-seed-boundary? artifact)))
    (is (= :incomplete (:status proof)))
    (is (false? (:phase-18-completion-gate-passed? proof)))
    (is (false? (:final-release-eligible? proof)))
    (is (true? (:clojure-seed-boundary? proof)))
    (is (= :incomplete (:status p15-proof)))
    (is (false? (:full-language-compiler-self-hosted? p15-proof)))
    (is (false? (:clojure-seed-retired? p15-proof)))
    (is (true? (:clojure-seed-boundary? p15-proof)))
    (is (= :self_hosted_public_binary_final_verification
           (:next-required-capability artifact)))
    (is (contains? diagnostics "P18T06003"))
    (is (contains? diagnostics "P18T06004"))
    (is (true? (:clojure-seed-boundary? boundary)))
    (is (true? (get-in boundary
                       [:seed-boundary-facts
                        :p15-clojure-seed-boundary?])))
    (is (false? (get-in boundary
                        [:seed-boundary-facts
                         :p15-clojure-seed-retired?])))
    (is (.isFile (java.io.File. bootstrap/p18-t06-final-proof-path)))
    (is (zero? (:exit version-result)))
    (is (str/includes? (:out version-result) ":phase \"P18-T02\""))
    (is (str/includes? (:out version-result)
                       ":packaged-jvm-cli? true"))
    (is (= 1 (:exit seedless-assert)))
    (is (str/includes? (:err seedless-assert) "P18T02001"))
    (is (zero? (:exit release-test-result)))
    (is (= :gravity/p18-t04-public-test-command-proof
           (:kind release-test-artifact)))
    (is (true? (get-in release-test-artifact
                       [:capability-based-proof
                        :public-test-command-passed?])))
    (is (true? (get-in release-test-artifact
                       [:capability-based-proof
                        :bootstrap-hosted?])))
    (is (false? (get-in release-test-artifact
                        [:capability-based-proof
                         :full-language-conformance?])))
    (is (= 1 (:exit release-test-overclaim)))
    (is (str/includes? (:err release-test-overclaim) "P18T04006"))))

