        (is (= "Hello Gravity\n" (:out jvm-run)))
        (is (= 1 (:exit unsupported)))
        (is (str/includes? (:err unsupported) "C14-TARGET"))
        (is (= 1 (:exit missing-output)))
        (is (str/includes? (:err missing-output) "C14-INPUT"))
        (is (= 1 (:exit duplicate-target)))
        (is (str/includes? (:err duplicate-target) "P18T04002")))
      (finally
        (doseq [path [jvm-output (str jvm-output ".gravity-artifact.edn")
                      c-output (str c-output ".c")
                      unsupported-output (str unsupported-output ".c")
                      (str unsupported-output ".manifest.edn")
                      (str unsupported-output ".source-map.edn")
                      (str unsupported-output ".provenance.edn")]]
          (java.nio.file.Files/deleteIfExists
           (.toPath (java.io.File. path))))))))

(deftest public-current-source-c-compile-routes-from-unrelated-cwd
  (let [root (.getCanonicalPath (java.io.File. "."))
        bin (str root "/bin/gravity")
        source (str root "/examples/hello.qst")
        nonce (str (System/nanoTime))
        output (str "target/public-c-unrelated-cwd-" nonce)
        actual-output (str root "/" output)]
    (try
      (let [result (run-process-in-directory
                    "/tmp"
                    (merge (into {} (System/getenv))
                           {"GRAVITY_BOOTSTRAP_ONLY" "1"})
                    [bin "compile" source "--target" "c"
                     "--lowering" "runtime-derived" "-o" output])
            artifact (edn/read-string (:out result))
            executable-result (run-bin actual-output)]
        (is (zero? (:exit result)) (:err result))
        (is (= :runtime-derived
               (get-in artifact [:target :lowering-mode])))
        (is (= :gravity/stage2-hosted-core-compiled-plan
               (:input-plan-kind artifact)))
        (is (= :p15-s23-stage2-compiler-driver
               (get-in artifact [:manifest :compiler-stage])))
        (is (= :gravity-stage2-compiler-driver-rules-v1
               (get-in artifact [:manifest :compiler-engine])))
        (is (true? (get-in artifact
                            [:manifest :stage2-compiler-driver-used?])))
        (is (re-find #"^sha256:"
                     (get-in artifact
                             [:manifest :compiler-driver-rule-hash])))
        (is (string? (get-in artifact
                             [:manifest :compiler-source-rule-hash])))
        (is (= (get-in artifact [:manifest :compiler-source-rule-hash])
               (get-in artifact [:provenance :compiler-source-rule-hash])))
        (is (true? (get-in artifact [:manifest :runtime-derived?])))
        (is (= source (get-in artifact [:provenance :source :path])))
        (is (zero? (:exit executable-result)))
        (is (= "Hello Gravity\n" (:out executable-result))))
      (finally
        (doseq [path [actual-output (str actual-output ".c")
                      (str actual-output ".manifest.edn")
                      (str actual-output ".source-map.edn")
                      (str actual-output ".provenance.edn")]]
          (java.nio.file.Files/deleteIfExists
           (.toPath (java.io.File. path))))))))

(deftest public-current-source-c-compile-creates-nested-output-directory
  (let [nonce (str (System/nanoTime))
        root-directory (str "target/public-c-nested-" nonce)
        output (str root-directory "/nested/hello")]
    (try
      (let [result (run-thin-bin "bin/gravity" "compile"
                                 "examples/hello.gravity"
                                 "--target" "c" "-o" output)
            artifact (edn/read-string (:out result))
            executable-result (run-bin output)]
        (is (zero? (:exit result)) (:err result))
        (is (= :gravity/c-backend-artifact (:kind artifact)))
        (is (.isFile (java.io.File. output)))
        (is (zero? (:exit executable-result)))
        (is (= "Hello Gravity\n" (:out executable-result))))
      (finally
        (doseq [file (reverse (file-seq (java.io.File. root-directory)))]
          (.delete ^java.io.File file))))))

