              (is (= "C14-INPUT" (:id data)))
              (is (= :authenticated-stage2-compiler-artifact-record
                     (:missing-fact data))))))))))

(deftest stage2-plan-assembly-is-gravity-authored-and-seed-equivalent
  (let [source-path "compiler-plan-assembly.gravity"
        source-text stage2-gravity-plan-assembly-source
        emitter
        (:emitter
         (bootstrap/c-backend-stage2-plan-emitter-source-rule!
          source-path :c))
        macro-artifact (bootstrap/macro-source-artifact source-path source-text)
        module0 (assoc (:module macro-artifact)
                       :forms (:expanded-forms macro-artifact))
        function-table (bootstrap/stage0-function-table module0)
        module (assoc module0 :function-table function-table)
        artifact-binding
        (bootstrap/p15-s23-stage2-compiler-artifact-binding!
         emitter source-path :c)
        ordered-definitions (mapv identity (sort-by key function-table))
        seed-functions
        (into (sorted-map)
              (map (fn [[name definition]]
                     [name (bootstrap/p15-s23-stage2-seed-compile-function
                            emitter module definition)]))
              ordered-definitions)
        seed-summary
        (apply merge-with +
               (mapcat (fn [[_ function]]
                         (map bootstrap/stage0-instruction-summary
                              (:instructions function)))
                       seed-functions))
        seed-bindings
        (mapv (fn [[_ function]]
                (assoc (:binding function) :arity (:arity function)))
              seed-functions)
        invocation-count (atom 0)
        original-invoke @#'bootstrap/p15-s23-stage2-compiler-artifact-invoke
        plan
        (with-redefs
          [bootstrap/p15-s23-stage2-compiler-artifact-invoke
           (fn [function arguments]
             (when (= bootstrap/p15-s23-stage2-compiler-artifact-plan-assembly-function
                      function)
               (swap! invocation-count inc))
             (original-invoke function arguments))]
          (bootstrap/p15-s23-stage2-plan-emitter-compile-source
           emitter source-path source-text))
        other-path-plan
        (bootstrap/p15-s23-stage2-plan-emitter-compile-source
         emitter "other-root/compiler-plan-assembly.qst" source-text)]
    (is (= 1 @invocation-count))
    (is (= seed-functions (:functions plan)))
    (is (= seed-bindings (:binding-table plan)))
    (is (= seed-summary (:instruction-summary plan)))
    (is (= #{:io/write} (get-in plan [:effect-summary :inferred])))
    (is (= ['alpha 'beta 'main]
           (mapv :name (:binding-table plan))))
    (is (= :gravity-source (get-in plan [:compiler :plan-assembly-owner])))
    (is (true? (get-in plan [:compiler :plan-assembly-invoked?])))
    (is (true?
         (get-in plan
                 [:compiler :plan-assembly-generic-bridge-residual?])))
    (is (= (:artifact-hash artifact-binding)
           (get-in plan [:compiler :plan-assembly-artifact-hash])))
    (is (= (:plan-id plan) (:plan-id other-path-plan)))
    (is (not= (get-in plan [:source :path])
              (get-in other-path-plan [:source :path])))
    (is (= "L3-UNKNOWN-ALIAS"
           (diagnostic-id
            #(bootstrap/p15-s23-stage2-plan-emitter-compile-source
              emitter "missing-main.gravity"
              (str "(ns compiler.assembly.missing "
                   "(:profile :hosted) (:target :jvm) "
                   "(:effects #{}) (:capabilities #{}) (:safety :safe))\n"
                   "(defn helper [] (do))\n")))))
    (is (= "L2-MAIN-ARITY"
           (diagnostic-id
            #(bootstrap/p15-s23-stage2-plan-emitter-compile-source
              emitter "main-arity.gravity"
              (str/replace source-text "(defn main []"
                           "(defn main [argument]")))))))

(deftest stage2-plan-assembly-handles-a-bounded-many-function-product
  (let [definitions
        (apply str
               (map #(format "(defn f%03d [] (do))\n" %) (range 512)))
        source-text
        (str "(ns compiler.assembly.many (:profile :hosted) "
             "(:target :jvm) (:effects #{}) (:capabilities #{}) "
             "(:safety :safe))\n"
             definitions
             "(defn main [] (do))\n")
        emitter
        (:emitter
         (bootstrap/c-backend-stage2-plan-emitter-source-rule!
          "many-functions.gravity" :c))
        plan
        (bootstrap/p15-s23-stage2-plan-emitter-compile-source
         emitter "many-functions.gravity" source-text)
        header
        (str "(ns compiler.assembly.scale (:profile :hosted) "
             "(:target :jvm) (:effects #{}) (:capabilities #{}) "
             "(:safety :safe))\n")
        flat-plan
        (bootstrap/p15-s23-stage2-plan-emitter-compile-source
         emitter "flat-body.gravity"
         (str header "(defn main []"
              (apply str (repeat 2048 " nil")) ")\n"))
        bindings
        (str/join " " (map #(str "x" % " " %) (range 512)))
        let-plan
        (bootstrap/p15-s23-stage2-plan-emitter-compile-source
         emitter "many-bindings.gravity"
         (str header "(defn main [] (let [" bindings "] x511))\n"))
        entries
        (str/join " " (map #(str ":k" % " " %) (range 512)))
        map-plan
        (bootstrap/p15-s23-stage2-plan-emitter-compile-source
         emitter "many-map-entries.gravity"
         (str header "(defn main [] {" entries "})\n"))]
    (is (= 513 (count (:functions plan))))
    (is (= 513 (count (:binding-table plan))))
    (is (= (vec (sort-by str (keys (:functions plan))))
           (mapv :name (:binding-table plan))))
    (is (re-matches #"sha256:[0-9a-f]{64}" (:plan-id plan)))
    (is (= 2048
           (count (get-in flat-plan [:functions 'main :instructions]))))
    (is (= 512
           (count (get-in let-plan
                          [:functions 'main :instructions 0 :bindings]))))
    (is (= 512
           (count (get-in map-plan
                          [:functions 'main :instructions 0 :entries]))))))

(deftest stage2-expression-lowering-preserves-seed-plan-and-diagnostics
  (let [source-path "compiler-artifact-plan.gravity"
        source-text stage2-gravity-compiler-artifact-source
        emitter
        (:emitter
         (bootstrap/c-backend-stage2-plan-emitter-source-rule!
          source-path :c))
        macro-artifact (bootstrap/macro-source-artifact source-path source-text)
        module0 (assoc (:module macro-artifact)
                       :forms (:expanded-forms macro-artifact))
        function-table (bootstrap/stage0-function-table module0)
        module (assoc module0 :function-table function-table)
        artifact-binding
        (bootstrap/p15-s23-stage2-compiler-artifact-binding!
         emitter source-path :c)]
    (clojure.core/binding
      [bootstrap/*p15-s23-stage2-compiler-artifact-binding* artifact-binding]
      (doseq [[name definition] function-table]
        (is (= (bootstrap/p15-s23-stage2-seed-compile-function
                emitter module definition)
               (bootstrap/p15-s23-stage2-compile-function
                emitter module definition))
            (str "Gravity lowering must preserve the seed plan for " name)))
      (doseq [form [[1 "two"] {:b 2 :a 1} #{:z :a}]]
        (is (= (bootstrap/p15-s23-stage2-seed-compile-expr
                emitter module #{} form)
               (bootstrap/p15-s23-stage2-compile-expr
                emitter module #{} form))
            (str "Gravity lowering must preserve collection plan "
                 (pr-str form)))))
    (doseq [[body expected]
            [["(unknown-call 1)" "L2-UNKNOWN-CORE-FORM"]
             ["(quot 4 2)" "L2-UNKNOWN-CORE-FORM"]
             ["(subvec [1 2] 0 1)" "L2-UNKNOWN-CORE-FORM"]
             ["(vec [1 2])" "L2-UNKNOWN-CORE-FORM"]
             ["(host-reflect String)" "P4-HOST-REFLECTION"]
             ["(let [1 2] 3)" "L2-LET-BINDING"]]]
      (let [invalid-source
            (str "(ns compiler.artifact.reject (:profile :hosted) "
                 "(:target :jvm) (:effects #{}) (:capabilities #{}) "
                 "(:safety :safe))\n(defn main [] " body ")\n")]
        (is (= expected
               (diagnostic-id
                #(bootstrap/stage2-runtime-derived-packet
                  "compiler-artifact-reject.gravity" invalid-source :c))))))))

(deftest stage2-expression-lowering-fails-closed-on-source-tamper
  (let [compiler-text (slurp "bootstrap/gravity/p15_s23/compiler.gravity")
        runtime-text (slurp "bootstrap/gravity/p15_s23/runtime.gravity")
        emitter-text (slurp "bootstrap/gravity/p15_s23/emitter.gravity")]
    (doseq [[case-name mutate expected-id expected-fact]
            [[:missing (constantly nil) "P15S23Q001"
              :stage2-expression-lowering-artifact]
             [:shape #(str/replace-first
                       %
                       "[emitter module definition]"
                       "[emitter module]")
              "P15S23Q002"
              :stage2-expression-lowering-function-shape]
             [:assembly-shape #(str/replace-first
                                %
                                "[emitter module definitions]"
                                "[emitter module]")
              "P15S23Q002"
              :stage2-expression-lowering-function-shape]
             [:semantic #(str/replace-first
                          %
                          ":status :ready"
                          ":status :tampered")
              "P15S23Q002"
              :stage2-expression-lowering-semantic-hash]
             [:assembly-semantic #(str/replace-first
                                   %
                                   ":effect-summary"
                                   ":effect-summary-tampered")
              "P15S23Q002"
              :stage2-expression-lowering-semantic-hash]
             [:source-only #(str "; source identity tamper\n" %)
              "P15S23Q002"
              :stage2-expression-lowering-source-content-hash]]]
      (with-temp-directory
        (str "gravity-compiler-artifact-" (name case-name) "-")
        (fn [root]
          (let [compiler-path (.resolve root "compiler.gravity")
                runtime-path (.resolve root "runtime.gravity")
                emitter-path (.resolve root "emitter.gravity")
                output-path (.resolve root "output")]
            (spit (.toFile compiler-path) compiler-text)
            (spit (.toFile runtime-path) runtime-text)
            (when-let [tampered (mutate emitter-text)]
              (spit (.toFile emitter-path) tampered))
            (let [diagnostic
                  (diagnostic-data
                   #(with-redefs
                      [bootstrap/c-backend-resolve-p15-s23-compiler-source-path
                       (constantly (.toString compiler-path))]
                      (bootstrap/js-ts-backend-source-artifact
                       "compiler-artifact-tamper.gravity"
                       stage2-gravity-compiler-artifact-source
                       {:target :js-ts
                        :output-path (.toString output-path)
                        :emit? true})))]
              (is (= expected-id (:id diagnostic)))
              (is (= expected-fact (:missing-fact diagnostic)))
              (is (not (.exists (.toFile output-path)))))))))))

(deftest stage2-expression-lowering-identity-is-cross-root-neutral
  (let [compiler-text (slurp "bootstrap/gravity/p15_s23/compiler.gravity")
        runtime-text (slurp "bootstrap/gravity/p15_s23/runtime.gravity")
        emitter-text (slurp "bootstrap/gravity/p15_s23/emitter.gravity")]
    (with-temp-directory
      "gravity-compiler-artifact-left-"
      (fn [left]
        (with-temp-directory
          "gravity-compiler-artifact-right-"
          (fn [right]
            (let [write-root
                  (fn [root]
                    (let [compiler (.resolve root "compiler.gravity")]
                      (spit (.toFile compiler) compiler-text)
                      (spit (.toFile (.resolve root "runtime.gravity"))
                            runtime-text)
                      (spit (.toFile (.resolve root "emitter.gravity"))
                            emitter-text)
                      compiler))
                  left-compiler (write-root left)
                  right-compiler (write-root right)
                  compile-at
                  (fn [compiler]
                    (with-redefs
                      [bootstrap/c-backend-resolve-p15-s23-compiler-source-path
                       (constantly (.getCanonicalPath (.toFile compiler)))]
                      (bootstrap/c-backend-source-artifact
                       "compiler-artifact-root-neutral.gravity"
                       stage2-gravity-compiler-artifact-source
                       {:target :c :lowering-mode :runtime-derived})))
                  compile-js-at
                  (fn [compiler]
                    (with-redefs
                      [bootstrap/c-backend-resolve-p15-s23-compiler-source-path
                       (constantly (.getCanonicalPath (.toFile compiler)))]
                      (bootstrap/js-ts-backend-source-artifact
                       "compiler-artifact-root-neutral.gravity"
                       stage2-gravity-compiler-artifact-source
                       {:target :js-ts})))
                  compile-jvm-at
                  (fn [compiler]
                    (with-redefs
                      [bootstrap/c-backend-resolve-p15-s23-compiler-source-path
                       (constantly (.getCanonicalPath (.toFile compiler)))]
                      (bootstrap/jvm-backend-source-artifact
                       "compiler-artifact-root-neutral.gravity"
                       stage2-gravity-compiler-artifact-source)))
                  left-artifact (compile-at left-compiler)
                  right-artifact (compile-at right-compiler)
                  left-js (compile-js-at left-compiler)
                  right-js (compile-js-at right-compiler)
                  left-jvm (compile-jvm-at left-compiler)
                  right-jvm (compile-jvm-at right-compiler)]
              (is (= (:artifact-id left-artifact)
                     (:artifact-id right-artifact)))
              (is (= (:manifest-hash left-artifact)
                     (:manifest-hash right-artifact)))
              (is (= (:provenance-hash left-artifact)
                     (:provenance-hash right-artifact)))
              (is (= (get-in left-artifact
                             [:expression-lowering-artifact :artifact-hash])
                     (get-in right-artifact
                             [:expression-lowering-artifact :artifact-hash])))
              (is (= (:artifact-id left-js) (:artifact-id right-js)))
              (is (= (:manifest-hash left-js) (:manifest-hash right-js)))
              (is (= (:provenance-hash left-js)
                     (:provenance-hash right-js)))
              (is (= (:artifact-id left-jvm) (:artifact-id right-jvm)))
              (is (= (:manifest-hash left-jvm)
                     (:manifest-hash right-jvm)))
              (is (= (:provenance-hash left-jvm)
                     (:provenance-hash right-jvm)))
              (is (= (:expression-lowering-artifact left-artifact)
                     (:expression-lowering-artifact right-artifact)))
              (is (not=
                   (get-in left-artifact
                           [:provenance :actual-paths
                            :stage2-expression-lowering-source])
                   (get-in right-artifact
                           [:provenance :actual-paths
                            :stage2-expression-lowering-source])))
              (is (= (:stage2-expression-lowering-artifact left-js)
                     (:stage2-expression-lowering-artifact right-js)))
              (is (not=
                   (get-in left-js
                           [:provenance :actual-paths
                            :stage2-expression-lowering-source])
                   (get-in right-js
                           [:provenance :actual-paths
                            :stage2-expression-lowering-source])))
              (doseq [[left-product right-product]
                      [[left-artifact right-artifact]
                       [left-js right-js]
                       [left-jvm right-jvm]]]
                (let [left-record
                      (or (:closed-plan-runtime-target-record left-product)
                          (get-in left-product
                                  [:manifest :closed-plan-runtime]))
                      right-record
                      (or (:closed-plan-runtime-target-record right-product)
                          (get-in right-product
                                  [:manifest :closed-plan-runtime]))
                      left-context
                      (or (:closed-runtime-validation-context left-product)
                          (get-in left-product
                                  [:manifest-validation-context
                                   :closed-runtime-context]))
                      right-context
                      (or (:closed-runtime-validation-context right-product)
                          (get-in right-product
                                  [:manifest-validation-context
                                   :closed-runtime-context]))
                      left-runtime-path
                      (get-in left-product
                              [:provenance :actual-paths
                               :stage2-runtime-artifact-source])
                      right-runtime-path
                      (get-in right-product
                              [:provenance :actual-paths
                               :stage2-runtime-artifact-source])]
                  (is (= (bootstrap/p15-s23-closed-runtime-target-semantic-record
                          left-record)
                         (bootstrap/p15-s23-closed-runtime-target-semantic-record
                          right-record)))
                  (is (not= left-runtime-path right-runtime-path))
                  (is (= left-runtime-path
                         (get-in left-record
                                 [:actual-path-binding :actual-path])))
                  (is (= right-runtime-path
                         (get-in right-record
                                 [:actual-path-binding :actual-path])))
                  (is (not= (get-in left-record
                                    [:actual-path-binding :binding-hash])
                            (get-in right-record
                                    [:actual-path-binding :binding-hash])))
                  (is (bootstrap/p15-s23-closed-runtime-target-record-authentic?
                       left-record left-context))
                  (is (bootstrap/p15-s23-closed-runtime-target-record-authentic?
                       right-record right-context)))))))))))

(deftest hosted-js-ts-backend-emits-deterministic-sidecars-and-executable
  (let [source-text
        (str "(ns js.target.emit (:profile :hosted) (:target :jvm) "
             "(:effects #{:io/write}) (:capabilities #{:io/stdout}))\n"
             "(defn main [] (println \"emitted\"))\n")]
    (with-temp-directory
      "gravity-js-ts-emission-"
      (fn [directory]
        (let [left-output (.toString (.resolve directory "left/program"))
              right-output (.toString (.resolve directory "right/renamed"))
              left (bootstrap/js-ts-backend-source-artifact
                    "virtual-a.gravity" source-text
                    {:target :js :output-path left-output :emit? true})
              right (bootstrap/js-ts-backend-source-artifact
                     "virtual-b.qst" source-text
                     {:target :js-ts :output-path right-output :emit? true})
              c-output (.toString (.resolve directory "program-c"))
              c-artifact
              (bootstrap/c-backend-source-artifact
               "virtual-c.gravity" source-text
               {:target :c
                :lowering-mode :runtime-derived
                :compile? true
                :c-source-path (str c-output ".c")
                :executable-path c-output
                :manifest-path (str c-output ".manifest.edn")
                :source-map-path (str c-output ".source-map.edn")
                :provenance-path (str c-output ".provenance.edn")})
              paths (get-in left [:provenance :actual-paths :outputs])
              execution (run-bin "node" (:javascript paths))]
          (is (= (:artifact-id left) (:artifact-id right)))
          (is (= (:manifest-hash left) (:manifest-hash right)))
          (is (= (:provenance-hash left) (:provenance-hash right)))
          (is (= 6 (count paths)))
          (doseq [path (vals paths)]
            (is (.isFile (java.io.File. path))))
          (doseq [[kind path]
                  (select-keys paths
                               [:javascript :typescript-declarations
                                :source-map :package-metadata])]
            (is (= (get-in left [:manifest :content-hashes kind])
                   (str "sha256:"
                        (bootstrap/sha256-bytes-hex
                         (java.nio.file.Files/readAllBytes
                          (.toPath (java.io.File. path))))))))
          (is (.canExecute (java.io.File. (:javascript paths))))
          (is (zero? (:exit execution)))
          (is (= "emitted\n" (:out execution)))
          (is (= (:compiled-execution-output left)
                 (:compiled-execution-output c-artifact)))
          (is (str/includes? (slurp (:javascript paths))
                             "//# sourceMappingURL=program.mjs.map"))
          (is (str/includes? (slurp (:typescript-declarations paths))
                             "export {};"))
          (is (str/includes? (slurp (:source-map paths))
                             "\"version\":3"))
          (is (not (str/includes? (slurp (:source-map paths))
                                  "\"mappings\":\"\"")))
          (is (str/includes? (slurp (:source-map paths))
                             "\"generatedOrigins\""))
          (is (str/includes? (slurp (:source-map paths))
                             "(defn main"))
          (let [generated-lines
                (count (str/split (:javascript-source left) #"\n" -1))
                origin-count
                (count (re-seq #"\"generatedLine\"" (:source-map left)))
                mapping-value
                (second (re-find #"\"mappings\":\"([^\"]+)\""
                                 (:source-map left)))]
            (is (= generated-lines origin-count))
            (is (= generated-lines
                   (count (str/split mapping-value #";" -1)))))
          (is (str/includes? (slurp (:package-metadata paths))
                             "\"type\":\"module\""))
          (is (str/includes? (slurp (:package-metadata paths))
                             "\"sideEffects\":true"))
          (is (true? (get-in left [:manifest :module :side-effects])))
          (is (= "B6-MANIFEST"
                 (diagnostic-id
                  #(bootstrap/js-ts-backend-validate-manifest!
                    "effect-tamper.gravity"
                    (-> (:manifest left)
                        (dissoc :manifest-hash)
                        (assoc-in [:effects :declared] #{}))
                    (:closed-runtime-validation-context left)))))
          (is (= "B6-MANIFEST"
                 (diagnostic-id
                  #(bootstrap/js-ts-backend-validate-manifest!
                    "coordinated-effect-tamper.gravity"
                    (-> (:manifest left)
                        (dissoc :manifest-hash)
                        (assoc-in [:module :side-effects] false)
                        (assoc :host-globals []))
                    (:closed-runtime-validation-context left)))))
          (is (= "B6-MANIFEST"
                 (diagnostic-id
                  #(bootstrap/js-ts-backend-validate-manifest!
                    "safety-tamper.gravity"
                    (-> (:manifest left)
                        (dissoc :manifest-hash)
                        (assoc-in [:safety :mode] :unsafe))
                    (:closed-runtime-validation-context left)))))
          (is (= (:manifest left)
                 (edn/read-string (slurp (:manifest paths)))))
          (is (= (:provenance left)
                 (edn/read-string (slurp (:provenance paths)))))
          (is (= (:source (:provenance left))
                 nil)))))))

(deftest hosted-js-ts-backend-preserves-empty-stdout-without-host-authority
  (let [source-text
        (str "(ns js.target.empty (:profile :hosted) (:target :js-ts) "
             "(:effects #{}) (:capabilities #{}))\n"
             "(defn main [] (do))\n")
        artifact (bootstrap/js-ts-backend-source-artifact
                  "empty.gravity" source-text {:target :js})
        overdeclared-text
