(def ^:private gravity-c6c10-accepted-source
  (str "(ns gravity.c6c10.probe (:profile :hosted) (:target :jvm) "
       "(:effects #{}) (:capabilities #{}) (:safety :safe) "
       "(:exports [main]))\n"
       "(defn main [] nil)\n"))

