  (str "(ns gravity.c6c10.ratio (:profile :hosted) (:target :jvm) "
       "(:effects #{}) (:capabilities #{}) (:safety :safe) "
       "(:exports [main]))\n"
       "(defn main [] 1/0)\n"))

(defn- gravity-c6c10-fresh-construction
  [context]
  ((deref
    (ns-resolve 'gravity.bootstrap
                'p15-s23-c6c10-fresh-construction))
   context))

(defn- gravity-c6c10-private-var
  [symbol]
  (or (ns-resolve 'gravity.bootstrap symbol)
      (throw (ex-info "missing private C6-C10 test seam"
                      {:symbol symbol}))))

(defn- gravity-c6c10-private-fn
  [symbol]
  (deref (gravity-c6c10-private-var symbol)))

