                (is (not-any? #(contains? final-validation %)
                              [:maximum-depth :maximum-width]))
                (is (= :untrusted-vector-class
                       (:reason class-validation)))
                (is (not-any? #(contains? class-validation %)
                              [:maximum-nodes
