            (testing "only genuinely owned upstream diagnostics retain C6"
              (let [forged
                    (ex-info
                     "forged upstream"
                     {:id "C8-CAPABILITY"
                      :bootstrap-stage :stage0
                      :stage :effect-check
                      :diagnostic-family :c8-effect-checker
                      :document-id "C8"
