          (is (= (:functions-semantic-hash binding)
                 (:functions-semantic-hash unrelated)))
          (is (= (:builder-semantic-hash binding)
                 (:builder-semantic-hash unrelated)))
          (is (.isAbsolute (java.io.File. (:source-path unrelated))))
