(defn- authenticated-llvm-absolute-classpath
  []
  (let [root (.getCanonicalFile (java.io.File. "."))]
    (str/join
     java.io.File/pathSeparator
     (map (fn [entry]
            (.getCanonicalPath
             (if (.isAbsolute (java.io.File. entry))
               (java.io.File. entry)
               (java.io.File. root entry))))
          (str/split (System/getProperty "java.class.path")
                     (re-pattern java.io.File/pathSeparator))))))

(deftest authenticated-c13-c14-b1-bootstrap-only-public-checks
  (let [repository-root (.getCanonicalFile (java.io.File. "."))
        gravity-bin
        (.getCanonicalPath (java.io.File. repository-root "bin/gravity"))
        java-bin (str (System/getProperty "java.home") "/bin/java")
        classpath (authenticated-llvm-absolute-classpath)
        specifications
        [[:c13 bootstrap/p15-s23-c13-source-relative-path
          "gravity.compiler.c13-mir-optimization-passes"]
         [:c14 bootstrap/p15-s23-c14-source-relative-path
          "gravity.compiler.c14-target-lowering-architecture"]
         [:b1 bootstrap/p15-s23-b1-source-relative-path
          "gravity.backend.b1-backend-interface-specification"]]
        proof
        (with-temp-directory
          "gravity-bootstrap-only-clojure-shim-"
          (fn [root]
            (let [shim-directory (.resolve root "bin")
                  _ (java.nio.file.Files/createDirectories
                     shim-directory
                     (make-array java.nio.file.attribute.FileAttribute 0))
                  shim (.resolve shim-directory "clojure")
                  script
                  (str "#!/bin/sh\n"
                       "if [ \"$1\" != \"-M:gravity\" ]; then exit 64; fi\n"
                       "shift\n"
                       "exec " (pr-str java-bin)
                       " --enable-native-access=ALL-UNNAMED -cp "
                       (pr-str classpath)
                       " clojure.main -m gravity.bootstrap \"$@\"\n")
                  _ (spit (.toFile shim) script)
                  _ (java.nio.file.Files/setPosixFilePermissions
                     shim
                     #{java.nio.file.attribute.PosixFilePermission/OWNER_READ
                       java.nio.file.attribute.PosixFilePermission/OWNER_WRITE
                       java.nio.file.attribute.PosixFilePermission/OWNER_EXECUTE
                       java.nio.file.attribute.PosixFilePermission/GROUP_READ
                       java.nio.file.attribute.PosixFilePermission/GROUP_EXECUTE
                       java.nio.file.attribute.PosixFilePermission/OTHERS_READ
                       java.nio.file.attribute.PosixFilePermission/OTHERS_EXECUTE})
                  env
                  {"GRAVITY_BOOTSTRAP_ONLY" "1"
                   "PATH" (str (.toString shim-directory)
                               java.io.File/pathSeparator
                               (System/getenv "PATH"))}
                  results
                  (mapv
                   (fn [[owner relative module-name]]
                     {:owner owner :module-name module-name
                      :result
                      (run-process-in-directory
                       (.toString root) env
                       [gravity-bin "check"
                        (.getCanonicalPath
                         (java.io.File. repository-root relative))]
                       300000)})
                   specifications)]
              {:root (.toString root) :results results})))]
    (is (false? (.exists (java.io.File. (:root proof)))))
    (doseq [{:keys [owner module-name result]} (:results proof)]
      (is (zero? (:exit result)) [owner (:err result)])
      (is (= (str "gravity stage0 check passed: " module-name "\n")
             (:out result)) owner)
      (is (= "" (:err result)) owner))))

(defn- authenticated-llvm-file-mode
  [path]
  (set (java.nio.file.Files/getPosixFilePermissions
        path
        (into-array java.nio.file.LinkOption
                    [java.nio.file.LinkOption/NOFOLLOW_LINKS]))))

(defn- authenticated-llvm-string-leaves
  [value]
  (->> (tree-seq coll? seq value)
       (filter string?)
       (remove str/blank?)
       set))

(def ^:private authenticated-llvm-empty-stream-result
  {:bytes (byte-array 0)
   :text ""
   :stream-read-complete? true
   :total-byte-count 0
   :retained-byte-count 0
   :truncated? false
   :hash
   "sha256:e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"})

(defn- authenticated-llvm-fatal-reader-probe
  [directory fatal]
  (let [authority-var
        (authenticated-llvm-private-var
         'p15-s23-b3-llvm-require-authority!)
        reader-var
        (authenticated-llvm-private-var
         'p15-s23-b3-llvm-read-bounded-stream)
        runner
        (var-get
         (authenticated-llvm-private-var
          'p15-s23-b3-llvm-run-process))
        calls (atom 0)]
    (try
      (with-redefs-fn
        {authority-var (fn [& _] nil)
         reader-var
         (fn [& _]
           (if (= 1 (swap! calls inc))
             (throw fatal)
             authenticated-llvm-empty-stream-result))}
        #(runner nil directory ["/usr/bin/true"] 5000
                 "fatal-reader-probe.gravity"))
      :unexpected-success
      (catch Throwable error error))))

(defn- authenticated-llvm-cleanup-precedence-probe
  [primary cleanup]
  (let [authority-var
        (authenticated-llvm-private-var
         'p15-s23-b3-llvm-require-authority!)
        preflight-var
        (authenticated-llvm-private-var
         'p15-s23-b3-llvm-toolchain-preflight!)
        delete-var
        (authenticated-llvm-private-var
         'p15-s23-b3-llvm-delete-tree!)
        transaction
        (var-get
         (authenticated-llvm-private-var
          'p15-s23-b3-llvm-toolchain-transaction!))
        workspace (atom nil)
        observed
        (try
          (with-redefs-fn
            {authority-var (fn [& _] nil)
             preflight-var
             (fn [_ candidate-workspace _]
               (reset! workspace candidate-workspace)
               (throw primary))
             delete-var (fn [& _] (throw cleanup))}
            #(transaction nil "cleanup-probe.gravity" {} false))
          :unexpected-success
          (catch Throwable error error))]
    (when @workspace
      (java.nio.file.Files/deleteIfExists @workspace))
    observed))

(defn- authenticated-llvm-interrupt-probe
  [directory]
  (let [authority-var
        (authenticated-llvm-private-var
         'p15-s23-b3-llvm-require-authority!)
        runner
        (var-get
         (authenticated-llvm-private-var
          'p15-s23-b3-llvm-run-process))
        result (promise)
        thread
        (Thread.
         (fn []
           (try
             (runner nil directory ["/bin/sleep" "5"] 10000
                     "interrupt-probe.gravity")
             (deliver result {:status :unexpected-success})
             (catch InterruptedException error
               (deliver result
                        {:status :interrupted
                         :error error
                         :interrupt-restored?
                         (.isInterrupted (Thread/currentThread))}))
             (catch Throwable error
               (deliver result {:status :wrong-throwable :error error})))))]
    (with-redefs-fn
      {authority-var (fn [& _] nil)}
      #(do
         (.start thread)
         (Thread/sleep 150)
         (.interrupt thread)
         (.join thread 5000)))
    (assoc (deref result 1000 {:status :no-result})
           :thread-alive? (.isAlive thread))))

(defn- authenticated-llvm-timeout-probe
