              _ (java.nio.file.Files/deleteIfExists symlink-parent)
              verify-publication
              (var-get
               (authenticated-llvm-private-var
                'p15-s23-b3-llvm-verify-publication!))
              alias-parent (.resolve root "published-alias")
              _ (java.nio.file.Files/createSymbolicLink
                 alias-parent root
                 (make-array java.nio.file.attribute.FileAttribute 0))
              aliased-provenance
              (assoc (:actual-path-provenance left)
                     :publication-path
                     (.toString (.resolve alias-parent "left-bundle")))
              alias-artifact
              (assoc left
                     :actual-path-provenance aliased-provenance
                     :actual-path-binding-id
                     (bootstrap/p15-s23-b3-llvm-actual-path-binding-id
                      (:semantic-id left) aliased-provenance))
              alias-data
              (diagnostic-data
               #(with-redefs-fn
                  {authority-var (fn [& _] nil)}
                  (fn [] (verify-publication nil alias-artifact))))
              _ (java.nio.file.Files/deleteIfExists alias-parent)
              extra-receipt-provenance
              (assoc-in (:actual-path-provenance left)
                        [:publication-receipt :hostile-extra]
                        "must-not-pass")
              extra-receipt-artifact
              (assoc left
                     :actual-path-provenance extra-receipt-provenance
                     :actual-path-binding-id
                     (bootstrap/p15-s23-b3-llvm-actual-path-binding-id
                      (:semantic-id left) extra-receipt-provenance))
              extra-receipt-data
              (diagnostic-data
               #(with-redefs-fn
                  {authority-var (fn [& _] nil)}
                  (fn [] (verify-publication nil extra-receipt-artifact))))
              race-output (.resolve root "race-bundle")
              race-marker (.resolve race-output "attacker-marker")
              watch-service
              (.newWatchService (java.nio.file.FileSystems/getDefault))
              _ (.register root watch-service
                           (into-array
                            java.nio.file.WatchEvent$Kind
                            [java.nio.file.StandardWatchEventKinds/ENTRY_CREATE]))
              output-preflight
              (var-get
               (authenticated-llvm-private-var
                'p15-s23-b3-llvm-output-preflight!))
              publish-final
              (var-get
               (authenticated-llvm-private-var
                'p15-s23-b3-llvm-publish-final!))
              inventory-var
              (authenticated-llvm-private-var
               'p15-s23-b3-llvm-capped-directory-inventory!)
              original-inventory (var-get inventory-var)
              race-preflight
              (output-preflight first-candidate (.toString race-output)
                                (.toString left-path))
              race-triggered? (atom false)
              race-data
              (diagnostic-data
               #(with-redefs-fn
                  {inventory-var
                   (fn [candidate directory source-path expected-maximum]
                     (let [result
                           (original-inventory
                            candidate directory source-path expected-maximum)]
                       (when (and (= 6 expected-maximum)
                                  (= #{"program.ll" "program.o" "program"
                                       "manifest.edn" "provenance.edn"
                                       "conformance.edn"}
                                     result)
                                  (compare-and-set! race-triggered? false true))
                         (java.nio.file.Files/createDirectory
                          race-output
                          (make-array
                           java.nio.file.attribute.FileAttribute 0))
                         (spit (.toFile race-marker) "attacker-owned"))
                       result))}
                  (fn []
                    (publish-final
                     first-candidate left
                     (:payload (first transaction-values)) race-preflight
                     (fn [receipt]
                       (let [actual-path-provenance
                             (assoc (:actual-path-provenance left)
                                    :publication-path
                                    (:actual-output-directory receipt)
                                    :publication-receipt
                                    (dissoc receipt :actual-output-directory))]
                         (assoc left
                                :actual-path-provenance
                                actual-path-provenance
                                :actual-path-binding-id
                                (bootstrap/p15-s23-b3-llvm-actual-path-binding-id
                                 (:semantic-id left)
                                 actual-path-provenance))))))))
              watch-key
              (.poll watch-service 2 java.util.concurrent.TimeUnit/SECONDS)
              watch-events
              (if watch-key
                (mapv #(str (.context ^java.nio.file.WatchEvent %))
                      (.pollEvents watch-key))
                [])
              _ (when watch-key (.reset watch-key))
              race-record
              {:data race-data
               :triggered? @race-triggered?
               :watch-events watch-events
               :marker (when (java.nio.file.Files/exists
                              race-marker
                              (make-array java.nio.file.LinkOption 0))
                         (slurp (.toFile race-marker)))
               :destination-names
               (when (java.nio.file.Files/isDirectory
                      race-output
                      (make-array java.nio.file.LinkOption 0))
                 (set (seq (.list (.toFile race-output)))))}
              _ (.close watch-service)
              _ (java.nio.file.Files/deleteIfExists race-marker)
              _ (java.nio.file.Files/deleteIfExists race-output)
              tool-after-output
              (bootstrap/p15-s23-b3-llvm-tool-execution-snapshot)
              missing-native
              (authenticated-llvm-missing-native-probe root)
              fatal-errors
              [(AssertionError. "assertion-fatal")
               (LinkageError. "linkage-fatal")
               (OutOfMemoryError. "oom-fatal")
               (ThreadDeath.)]
              fatal-results
              (mapv (fn [fatal]
                      {:expected fatal
                       :observed
                       (authenticated-llvm-fatal-reader-probe root fatal)})
                    fatal-errors)
              primary-fatal (AssertionError. "primary-fatal")
              cleanup-fatal (LinkageError. "cleanup-fatal")
              primary-fatal-result
              (authenticated-llvm-cleanup-precedence-probe
               primary-fatal cleanup-fatal)
              ordinary-primary (Exception. "ordinary-primary")
              winning-cleanup (OutOfMemoryError. "winning-cleanup")
              cleanup-fatal-result
              (authenticated-llvm-cleanup-precedence-probe
               ordinary-primary winning-cleanup)
              timeout-result
              (authenticated-llvm-timeout-probe root)
              interrupt-result
              (authenticated-llvm-interrupt-probe root)
              b3-complete
              (bootstrap/p15-s23-b3-llvm-diagnostic-record
               "B3-MANIFEST" (.toString left-path) {}
               {:bounded-reason :legitimate})
              b3-forged-base
              (assoc-in b3-complete [:facts :bounded-reason]
                        "B3-FACT-SECRET")
              b3-forged-id
              (bootstrap/c15-stable-diagnostic-id b3-forged-base)
              b3-forged
              (assoc b3-forged-base
                     :diagnostic-id b3-forged-id
                     :ordering-key
                     ["B3-MANIFEST" (:stage b3-forged-base)
                      (get-in b3-forged-base [:primary :artifact])
                      b3-forged-id])
              b3-contained
              (diagnostic-data
               #(bootstrap/p15-s23-b3-llvm-contain-exception!
                 (.toString left-path) :forged-b3-diagnostic
                 (ex-info "B3-TOP-SECRET"
                          (merge b3-forged
                                 {:id "B3-MANIFEST"
                                  :hostile-extra "B3-EXTRA-SECRET"}))))
              staging-leftovers
              (set (filter #(str/starts-with?
                             % ".gravity-b3-final-publish-")
                           (seq (.list (.toFile root)))))]
          {:source authenticated-llvm-live-source
           :root (.toString root)
           :left {:artifact left :checked-core left-core
                  :c11 left-c11 :context left-context
                  :output left-output-record}
           :right {:artifact right :checked-core right-core
                   :c11 right-c11 :context right-context
                   :output right-output-record}
           :contextual-report contextual-report
           :diamond-lowering diamond-lowering
           :transactions
           {:before tool-before-live :after tool-after-live
            :count (count transaction-values)
            :records payload-summary}
           :tamper
           {:before tool-before-tamper :after tool-after-tamper
            :packet
            {:before packet-tamper-before :after packet-tamper-after
             :results packet-tamper-results}
            :target-c11 target-c11-data
            :unsupported unsupported-data
            :build build-tamper-data
            :request request-tamper-data
            :coherent coherent-data
            :dynamic-binding dynamic-binding-data
            :carried-b1 carried-b1-data
            :context-binding-genuine context-binding-genuine
            :context-source context-source-data
            :context-provenance-genuine context-provenance-genuine
            :declared-llvm declared-llvm-data}
           :output-probes
           {:before tool-before-output :after tool-after-output
            :collision collision-data :symlink symlink-data
            :alias alias-data :extra-receipt extra-receipt-data
            :last-moment-race race-record
            :missing-native missing-native
            :collision-directory-preserved?
            (java.nio.file.Files/isDirectory
             collision-output (make-array java.nio.file.LinkOption 0))
            :collision-directory-names
            (set (seq (.list (.toFile collision-output))))
            :real-parent-preserved?
            (java.nio.file.Files/isDirectory
             real-parent (make-array java.nio.file.LinkOption 0))
            :staging-leftovers staging-leftovers}
           :fatal
           {:readers fatal-results
            :primary-fatal primary-fatal
            :cleanup-fatal cleanup-fatal
            :primary-fatal-result primary-fatal-result
            :ordinary-primary ordinary-primary
            :winning-cleanup winning-cleanup
            :cleanup-fatal-result cleanup-fatal-result
            :timeout timeout-result
            :interrupt interrupt-result}
           :diagnostics {:b3-contained b3-contained}})))))

(deftest authenticated-llvm-public-error-and-hostile-carrier-boundaries
  (let [{:keys [left]} @authenticated-llvm-live-proof
        artifact (:artifact left)
        checked-core (:checked-core left)
        c11 (:c11 left)
        context (:context left)
        options-var
        (authenticated-llvm-private-var
         'p15-s23-b3-llvm-validated-options!)
        trusted-final-var
        (authenticated-llvm-private-var
         'p15-s23-b3-llvm-require-trusted-final-carrier!)
        bridge-build-var
        (authenticated-llvm-private-var
         'p15-s23-c13-c14-b1-build-internal!)
        c11-builder-var #'bootstrap/p15-s23-stage2-c11-mir-artifact
        before (bootstrap/p15-s23-b3-llvm-tool-execution-snapshot)
        contained
        (into
         (sorted-map)
         (for [[kind error]
               [[:assertion (AssertionError. "contained-error-secret")]
                [:linkage (LinkageError. "contained-error-secret")]]]
           [kind
            {:bridge-constructor
             (diagnostic-data
              #(with-redefs-fn
                 {bridge-build-var (fn [& _] (throw error))
                  c11-builder-var (fn [& _] c11)}
                 (fn []
                   (bootstrap/p15-s23-stage2-c13-c14-b1-packet-from-c11!
                    c11 checked-core context))))
             :bridge-verifier
             (diagnostic-data
              #(with-redefs-fn
                 {bridge-build-var (fn [& _] (throw error))
                  c11-builder-var (fn [& _] c11)}
                 (fn []
                   (bootstrap/p15-s23-stage2-c13-c14-b1-verification-report
                    (:c13-c14-b1-packet artifact) checked-core context))))
             :bridge-authentic?
             (with-redefs-fn
               {bridge-build-var (fn [& _] (throw error))
                c11-builder-var (fn [& _] c11)}
               (fn []
                 (bootstrap/p15-s23-stage2-c13-c14-b1-authentic?
                  (:c13-c14-b1-packet artifact) checked-core context)))
             :constructor
             (diagnostic-data
              #(with-redefs-fn
                 {options-var (fn [& _] (throw error))}
                 (fn []
                   (bootstrap/p15-s23-stage2-b3-llvm-artifact-from-c11!
                    c11 checked-core context))))
             :verifier
             (diagnostic-data
              #(with-redefs-fn
                 {trusted-final-var (fn [& _] (throw error))}
                 (fn []
                   (bootstrap/p15-s23-stage2-b3-llvm-verification-report
                    artifact checked-core context))))
             :authentic?
             (with-redefs-fn
               {trusted-final-var (fn [& _] (throw error))}
               (fn []
                 (bootstrap/p15-s23-stage2-b3-llvm-authentic?
                  artifact checked-core context)))}]))
        fatal-results
        (into
         (sorted-map)
         (for [[kind fatal]
               [[:oom (OutOfMemoryError. "fatal-oom")]
                [:thread-death (ThreadDeath.)]]]
           [kind
            {:expected fatal
             :bridge-constructor
             (try
               (with-redefs-fn
                 {bridge-build-var (fn [& _] (throw fatal))
                  c11-builder-var (fn [& _] c11)}
                 (fn []
                   (bootstrap/p15-s23-stage2-c13-c14-b1-packet-from-c11!
                    c11 checked-core context)))
               :unexpected-success
               (catch Throwable observed observed))
             :bridge-verifier
             (try
               (with-redefs-fn
                 {bridge-build-var (fn [& _] (throw fatal))
                  c11-builder-var (fn [& _] c11)}
                 (fn []
                   (bootstrap/p15-s23-stage2-c13-c14-b1-verification-report
                    (:c13-c14-b1-packet artifact) checked-core context)))
               :unexpected-success
               (catch Throwable observed observed))
             :bridge-authentic
             (try
               (with-redefs-fn
                 {bridge-build-var (fn [& _] (throw fatal))
                  c11-builder-var (fn [& _] c11)}
                 (fn []
                   (bootstrap/p15-s23-stage2-c13-c14-b1-authentic?
                    (:c13-c14-b1-packet artifact) checked-core context)))
               :unexpected-success
               (catch Throwable observed observed))
             :constructor
             (try
               (with-redefs-fn
                 {options-var (fn [& _] (throw fatal))}
                 (fn []
                   (bootstrap/p15-s23-stage2-b3-llvm-artifact-from-c11!
                    c11 checked-core context)))
               :unexpected-success
               (catch Throwable observed observed))
             :verifier
             (try
               (with-redefs-fn
                 {trusted-final-var (fn [& _] (throw fatal))}
                 (fn []
                   (bootstrap/p15-s23-stage2-b3-llvm-verification-report
                    artifact checked-core context)))
               :unexpected-success
               (catch Throwable observed observed))
             :authentic
             (try
               (with-redefs-fn
                 {trusted-final-var (fn [& _] (throw fatal))}
                 (fn []
                   (bootstrap/p15-s23-stage2-b3-llvm-authentic?
                    artifact checked-core context)))
               :unexpected-success
               (catch Throwable observed observed))}]))
        cyclic-carrier (java.util.HashMap.)
        _ (.put cyclic-carrier :cycle cyclic-carrier)
        hostile-values
        [(sorted-map :hostile true)
         (vec (range (inc bootstrap/p15-s23-c13-c14-b1-max-carrier-nodes)))
         cyclic-carrier
         (nth (iterate vector nil) 600)]
        hostile
        (mapv
         (fn [value]
           {:bridge
            (diagnostic-data
             #(bootstrap/p15-s23-stage2-c13-c14-b1-verification-report
               value checked-core context))
            :bridge-authentic?
            (bootstrap/p15-s23-stage2-c13-c14-b1-authentic?
             value checked-core context)
            :b3
            (diagnostic-data
             #(bootstrap/p15-s23-stage2-b3-llvm-verification-report
               value checked-core context))
            :b3-authentic?
            (bootstrap/p15-s23-stage2-b3-llvm-authentic?
             value checked-core context)})
         hostile-values)
        interrupt-probe
        (fn [invoke]
          (Thread/interrupted)
          (let [expected (InterruptedException. "bridge-interrupted")
                observed
                (try
                  (invoke expected)
                  :unexpected-success
                  (catch Throwable error error))
                restored? (.isInterrupted (Thread/currentThread))]
            (Thread/interrupted)
            {:expected expected :observed observed :restored? restored?}))
        interrupt-results
        [(interrupt-probe
          (fn [error]
            (with-redefs-fn
              {bridge-build-var (fn [& _] (throw error))
               c11-builder-var (fn [& _] c11)}
              (fn []
                (bootstrap/p15-s23-stage2-c13-c14-b1-packet-from-c11!
                 c11 checked-core context)))))
         (interrupt-probe
          (fn [error]
            (with-redefs-fn
              {bridge-build-var (fn [& _] (throw error))
               c11-builder-var (fn [& _] c11)}
              (fn []
                (bootstrap/p15-s23-stage2-c13-c14-b1-verification-report
                 (:c13-c14-b1-packet artifact) checked-core context)))))]
        after (bootstrap/p15-s23-b3-llvm-tool-execution-snapshot)]
    (is (= before after))
    (doseq [[kind {:keys [bridge-constructor bridge-verifier
                          bridge-authentic? constructor verifier authentic?]}]
            contained]
      (is (= ["B3-MANIFEST"
              (case kind
                :assertion :contained-c13-c14-b1-assertion
                :linkage :contained-c13-c14-b1-linkage)]
             ((juxt :id :missing-fact) bridge-constructor)) kind)
      (is (= ["B3-MANIFEST"
              (case kind
                :assertion :contained-c13-c14-b1-verifier-assertion
                :linkage :contained-c13-c14-b1-verifier-linkage)]
             ((juxt :id :missing-fact) bridge-verifier)) kind)
      (is (false? bridge-authentic?) kind)
      (is (= ["B3-MANIFEST"
              (case kind
                :assertion :contained-b3-constructor-assertion
                :linkage :contained-b3-constructor-linkage)]
             ((juxt :id :missing-fact) constructor)) kind)
      (is (= ["B3-MANIFEST"
              (case kind
                :assertion :contained-b3-verifier-assertion
                :linkage :contained-b3-verifier-linkage)]
             ((juxt :id :missing-fact) verifier)) kind)
      (is (false? authentic?) kind)
      (is (not (str/includes? (pr-str bridge-constructor) "secret")) kind)
      (is (not (str/includes? (pr-str bridge-verifier) "secret")) kind)
      (is (not (str/includes? (pr-str constructor) "secret")) kind)
      (is (not (str/includes? (pr-str verifier) "secret")) kind))
    (doseq [[kind {:keys [expected bridge-constructor bridge-verifier
                          bridge-authentic constructor verifier authentic]}]
            fatal-results]
      (is (identical? expected bridge-constructor) kind)
      (is (identical? expected bridge-verifier) kind)
      (is (identical? expected bridge-authentic) kind)
      (is (identical? expected constructor) kind)
      (is (identical? expected verifier) kind)
      (is (identical? expected authentic) kind))
    (doseq [{:keys [expected observed restored?]} interrupt-results]
      (is (identical? expected observed))
      (is (true? restored?)))
    (doseq [{:keys [bridge bridge-authentic? b3 b3-authentic?]} hostile]
      (is (= :gravity/diagnostic (:artifact bridge)))
      (is (= :gravity/diagnostic (:artifact b3)))
      (is (= (:diagnostic-id bridge)
             (bootstrap/c15-stable-diagnostic-id bridge)))
      (is (= (:diagnostic-id b3)
             (bootstrap/c15-stable-diagnostic-id b3)))
      (is (false? bridge-authentic?))
      (is (false? b3-authentic?)))))

(deftest authenticated-llvm-arm64-macos-emits-runs-and-is-reproducible
  (let [{:keys [root left right contextual-report diamond-lowering transactions]}
        @authenticated-llvm-live-proof
        left-artifact (:artifact left)
        right-artifact (:artifact right)
        left-packet (:c13-c14-b1-packet left-artifact)
        right-packet (:c13-c14-b1-packet right-artifact)
        left-projection
        (bootstrap/p15-s23-c13-c14-b1-reproducible-projection left-packet)
        right-projection
        (bootstrap/p15-s23-c13-c14-b1-reproducible-projection right-packet)
        canonical-left-projection
        (bootstrap/c-backend-canonical-value left-projection)
        canonical-right-projection
        (bootstrap/c-backend-canonical-value right-projection)
        bridge-report
        (bootstrap/p15-s23-c13-c14-b1-contextual-report-record left-packet)
        b1-source (slurp bootstrap/p15-s23-b1-source-relative-path)
        b1-plan
        (bootstrap/p15-s23-stage2-compiler-artifact-plan
         (:emitter
          (bootstrap/c-backend-stage2-plan-emitter-source-rule!
           bootstrap/p15-s23-b1-source-relative-path :llvm))
         bootstrap/p15-s23-b1-source-relative-path b1-source)
        b1-invoke
        (fn [function-name argument]
          (bootstrap/p15-s23-stage2-runtime-execute-function
           {:engine :b1-c14-contract-seam-test
            :compiler-artifact-plan? true}
           b1-plan function-name [argument]))
        left-output (:output left)
        right-output (:output right)
        left-sidecar-projection
        (get-in left-output [:provenance :c13-c14-b1-packet])
        right-sidecar-projection
        (get-in right-output [:provenance :c13-c14-b1-packet])
        expected-names
        #{"program.ll" "program.o" "program"
          "manifest.edn" "provenance.edn" "conformance.edn"}
        nonexecutable-permissions
        #{java.nio.file.attribute.PosixFilePermission/OWNER_READ
          java.nio.file.attribute.PosixFilePermission/OWNER_WRITE
          java.nio.file.attribute.PosixFilePermission/GROUP_READ
          java.nio.file.attribute.PosixFilePermission/OTHERS_READ}
        executable-permissions
        #{java.nio.file.attribute.PosixFilePermission/OWNER_READ
          java.nio.file.attribute.PosixFilePermission/OWNER_WRITE
          java.nio.file.attribute.PosixFilePermission/OWNER_EXECUTE
          java.nio.file.attribute.PosixFilePermission/GROUP_READ
          java.nio.file.attribute.PosixFilePermission/GROUP_EXECUTE
          java.nio.file.attribute.PosixFilePermission/OTHERS_READ
          java.nio.file.attribute.PosixFilePermission/OTHERS_EXECUTE}
        expected-tool-steps
        #{:xcrun-version :file-version :clang-path :ld-path :otool-path
          :sdk-path :sdk-version :otool-version :clang-version
          :clang-target-triple :clang-default-target :linker-version
          :llvm-to-object :link :file-format :mach-o-header
          :mach-o-load-commands :runtime-providers :run}
        tool-records (get-in left-artifact
                             [:toolchain-evidence :tool-records])
        tool-record-by-step (into {} (map (juxt :step identity))
                                  tool-records)
        physical-tool-record
        (get-in left-artifact
                [:actual-path-provenance :tool-installation-record])]
    (is (= :gravity/p15-s23-b3-authenticated-llvm-artifact
           (:kind left-artifact) (:kind right-artifact)))
    (is (= :gravity/p15-s23-stage2-gravity-checked-core-artifact
           (get-in left [:checked-core :kind])
           (get-in right [:checked-core :kind])))
    (is (= :gravity-source-pure
           (get-in left [:c11 :checked-core-ingress
                         :checked-core-ingress-mode])
           (get-in right [:c11 :checked-core-ingress
                          :checked-core-ingress-mode])))
    (is (= :passed (:status contextual-report)))
    (is (= 3 (:count transactions)))
    (is (= 57 (- (get-in transactions [:after :total])
                 (get-in transactions [:before :total]))))
    (is (= expected-tool-steps
           (set (keys (get-in transactions [:after :steps])))))
    (doseq [step expected-tool-steps]
      (is (= 3
             (- (get-in transactions [:after :steps step] 0)
                (get-in transactions [:before :steps step] 0)))
          step))
    (is (= 19 (count tool-records) (count tool-record-by-step)))
    (is (= (bootstrap/p15-s23-b3-llvm-expected-command-contracts)
           (into (sorted-map)
                 (map (fn [[step record]]
                        [step (:command-contract record)]))
                 tool-record-by-step)))
    (doseq [[step record] tool-record-by-step]
      (is (= :gravity/b3-bounded-tool-step (:artifact record)) step)
      (is (true? (:finished? record)) step)
      (is (false? (:timed-out? record)) step)
      (is (false? (:raw-output-retained? record)) step)
      (is (= bootstrap/p15-s23-b3-llvm-environment-policy
             (:environment-policy record)) step))
    (is (= "/Library/Developer/CommandLineTools/SDKs/MacOSX.sdk"
           (:sdk-locator-path physical-tool-record)))
    (is (= "/Library/Developer/CommandLineTools/SDKs/MacOSX26.5.sdk"
           (:sdk-effective-path physical-tool-record)))
    (is (= "/Library/Developer/CommandLineTools/usr/bin/clang"
           (:clang-locator-path physical-tool-record)
           (:clang-effective-path physical-tool-record)))
    (is (= "/Library/Developer/CommandLineTools/usr/bin/ld"
           (:ld-locator-path physical-tool-record)
           (:ld-effective-path physical-tool-record)))
    (is (= "/Library/Developer/CommandLineTools/usr/bin/otool"
           (:otool-locator-path physical-tool-record)))
    (is (= "/Library/Developer/CommandLineTools/usr/bin/llvm-otool"
           (:otool-effective-path physical-tool-record)))
    (is (every? :candidate-identical? (:records transactions)))
