  (closed-pure-source-with-main
   "(let [x 7] (if false (do x) -65))" {:exports '[main]}))

(def ^:private authenticated-wasm-zero-truthiness-source
  (closed-pure-source-with-main "(if 0 7 9)" {:exports '[main]}))

