        context (:context left-upstream)
        forged-sha (str "sha256:" (apply str (repeat 64 "0")))
        resealed-content-forgery
        (let [forgery
              (assoc-in left-artifact [:source-file :content]
                        "int main(void) { return 99; }\n")
              forgery
              (assoc forgery :semantic-id
                     (#'bootstrap/p15-s23-b2-c17-semantic-id forgery))
              forgery
              (assoc forgery :artifact-id
                     (#'bootstrap/p15-s23-b2-c17-artifact-id forgery))]
          (assoc forgery :actual-path-binding-id
                 (#'bootstrap/p15-s23-b2-c17-actual-path-binding-id
                  forgery)))
        deep-hostile-carrier
        (assoc
         left-artifact :source-file
         (loop [depth 0 value (:source-file left-artifact)]
           (if (= depth 600)
             value
             (recur (inc depth) {:nested value}))))
        mutations
        [(assoc left-artifact :semantic-id forged-sha)
         (assoc-in left-artifact [:source-file :content]
                   "int main(void) { return 99; }\n")
         (assoc-in left-artifact [:actual-path-provenance :source]
                   "/forged/program.gravity")
         (assoc-in left-artifact [:input-bindings :b1-artifact-id]
                   forged-sha)
         resealed-content-forgery
         deep-hostile-carrier]
        mutation-data
        (mapv
         (fn [candidate]
           (diagnostic-data
            #(bootstrap/p15-s23-stage2-b2-c17-verification-report
              candidate checked-core context)))
         mutations)
        unsupported
        [[:quote "'hello"]
         [:string "\"hello\""]
         [:large-result "256"]]
        unsupported-data
        (mapv
         (fn [[label body]]
           [label
            (diagnostic-data
             #(bootstrap/p15-s23-stage2-b2-c17-source-artifact!
               (str "b2-unsupported-" (name label) ".gravity")
               (closed-pure-source-with-main body {:exports '[main]})))])
         unsupported)]
    (is (= "B2-MANIFEST" (:id pin-data)) pin-data)
    (is (= :pinned-b2-gravity-source-identity
           (:missing-fact pin-data)) pin-data)
    (is (= :c (:target pin-data)) pin-data)
    (is (= :hosted-c17 (:dialect pin-data)) pin-data)
    (is (= :none (:helper pin-data)) pin-data)
    (is (= :hosted-c17 (get-in pin-data [:facts :dialect])) pin-data)
    (is (= :none (get-in pin-data [:facts :helper])) pin-data)
    (is (not (str/includes? (pr-str pin-data)
                            "repair-bounded-llvm-input")) pin-data)
    (is (not (str/includes? (pr-str pin-data) ":llvm")) pin-data)
    (doseq [data mutation-data]
      (is (contains? #{"B13-HASH" "B2-MANIFEST"} (:id data)) data)
      (is (= :c (:target data)) data)
      (is (= :hosted-c17 (:dialect data)) data)
      (is (= :none (:helper data)) data)
      (is (= :hosted-c17 (get-in data [:facts :dialect])) data)
      (is (= :none (get-in data [:facts :helper])) data)
      (is (not (str/includes? (pr-str data) "repair-bounded-llvm-input"))
          data)
      (is (not (str/includes? (pr-str data) ":llvm")) data))
    (doseq [[label data] unsupported-data]
      (is (= "C14-UNSUPPORTED" (:id data)) [label data])
      (is (= :c (:target data)) [label data])
      (is (= :hosted-c17 (:dialect data)) [label data])
      (is (= :none (:helper data)) [label data])
      (is (= :hosted-c17 (get-in data [:facts :dialect])) [label data])
      (is (= :none (get-in data [:facts :helper])) [label data])
      (is (= :c14-target-lowering (:stage data)) [label data])
      (is (not (str/includes? (pr-str data) "repair-bounded-llvm-input"))
          [label data])
      (is (not (str/includes? (pr-str data) ":llvm")) [label data]))))

(deftest authenticated-b2-source-api-preserves-canonical-reader-diagnostics
  (let [reader-cases
        [[:delimiter "(" "C2-DELIMITER" "STAGE1READER002"]
         [:metadata "^" "C2-METADATA" nil]
         [:set "#{1 1}" "C2-SET" nil]
         [:abbrev "'" "C2-ABBREV" nil]
         [:numeric "1e2e3" "C2-NUMERIC" "STAGE1READER007"]]
        reader-data
        (vec
         (for [[label source expected-id expected-engine] reader-cases
               extension [".gravity" ".qst"]]
           (let [path (str "b2-reader-" (name label) extension)]
             {:label label :path path :expected-id expected-id
              :expected-engine expected-engine
              :data
              (diagnostic-data
               #(bootstrap/p15-s23-stage2-b2-c17-source-artifact!
                 path source))})))]
    (doseq [{:keys [label path expected-id expected-engine data]}
            reader-data]
      (is (= expected-id (:id data)) [label data])
      (is (= (keyword expected-id) (:rule data)) [label data])
      (is (= :c2-reader (:diagnostic-family data)) [label data])
      (is (= :read-source (:stage data)) [label data])
      (is (= expected-engine (:reader-engine-diagnostic data))
          [label data])
      (is (= path (get-in data [:source-span :source])) [label data])
      (when (= label :numeric)
        (let [reader-state (:reader-state data)]
          (is (= "L1-NUMERIC" (:remapped-from data)) data)
          (is (nil? (get-in data [:facts :normative-c2-mapping])) data)
          (is (nil? (get-in data [:facts :catalog-gap])) data)
          (is (= bootstrap/p15-s23-stage2-gravity-reader-state-keys
                 (set (keys reader-state))) data)
          (is (bootstrap/p15-s23-stage2-reader-diagnostic-authentic?
               path "1e2e3" data data) data)
          (is (bootstrap/p15-s23-stage2-canonical-c2-diagnostic-authentic?
               path "1e2e3" data data) data)
          (doseq [candidate
                  [(assoc-in data [:reader-state :owner] :host)
                   (assoc-in data [:reader-state :reason] "malformed")
                   (assoc-in data [:reader-state :column-unit] :utf-16)
                   (update-in data [:reader-state :char-position] inc)
                   (assoc-in data [:reader-state :result-committed?] true)
                   (assoc-in data [:reader-state :unexpected] true)]]
            (is (false?
                 (bootstrap/p15-s23-stage2-reader-diagnostic-authentic?
                  path "1e2e3" candidate candidate)) candidate)
            (is (false?
                 (bootstrap/p15-s23-stage2-canonical-c2-diagnostic-authentic?
                  path "1e2e3" candidate candidate)) candidate))))
      (is (not (str/includes? (pr-str data)
                              "contained-b2-c17-source-diagnostic"))
          [label data])
      (is (not (str/includes? (pr-str data) "B2-MANIFEST"))
          [label data]))))

(defn- authenticated-b2-gate-b-private-var
  [symbol]
  (or (ns-resolve 'gravity.bootstrap symbol)
      (throw (ex-info "missing authenticated C17 Gate B test seam"
                      {:symbol symbol}))))

(defn- authenticated-b2-gate-b-with-home-temp-directory
  [prefix f]
  (let [requested-home
        (java.nio.file.Paths/get (System/getProperty "user.home")
                                 (make-array String 0))
        home
        (.toRealPath requested-home
                     (make-array java.nio.file.LinkOption 0))
        valid-home?
        (and (.isAbsolute home)
             (= home (.normalize home))
             (java.nio.file.Files/isDirectory
              home
              (into-array
               java.nio.file.LinkOption
               [java.nio.file.LinkOption/NOFOLLOW_LINKS]))
             (not (java.nio.file.Files/isSymbolicLink requested-home))
             (not (java.nio.file.Files/isSymbolicLink home)))
        _
        (when-not valid-home?
          (throw
           (ex-info "C17 publication test requires a real home directory"
                    {:home (.toString home)})))
        path
        (java.nio.file.Files/createTempDirectory
         home prefix
         (make-array java.nio.file.attribute.FileAttribute 0))]
    (try
      (f path)
      (finally
        (doseq [file (reverse (file-seq (.toFile path)))]
          (.delete file))
        (is (not (java.nio.file.Files/exists
                  path
                  (make-array java.nio.file.LinkOption 0)))
            (str "temporary C17 publication root survived: " path))))))

(deftest authenticated-b2-gate-b-darwin-provider-failures-are-bounded-and-owned
  (let [provider-call!
        (authenticated-b2-gate-b-private-var
         'p15-s23-b2-c17-gate-b-provider-call!)
        canonical-receipt
        (authenticated-b2-gate-b-private-var
         'p15-s23-b2-c17-gate-b-canonical-provider-receipt)
        cases
        [{:operation :native-preflight :reason :native-access-disabled
          :expected-id "B2-MANIFEST"
          :expected-missing
          :jdk26-native-access-required-for-c17-publication}
         {:operation :native-preflight :reason :missing-native-symbol
          :expected-id "B2-MANIFEST"
          :expected-missing :jdk26-darwin-c17-publication-ffi-binding}
         {:operation :authenticate-destination :reason :destination-exists
          :expected-id "B2-MANIFEST"
          :expected-missing
          :collision-free-regular-c17-output-directory}
         {:operation :verify-publication
          :reason :invalid-publication-receipt
          :expected-id "B13-SCHEMA"
          :expected-missing :exact-descriptor-relative-c17-bundle}
         {:operation :fstat :reason :descriptor-stat-failed
          :expected-id "B13-PROVENANCE"
          :expected-missing
          :descriptor-relative-c17-publication-provenance
          :return-fact :provider-return-code}
         {:operation :fcntl-address :reason :descriptor-path-failed
          :expected-id "B13-PROVENANCE"
          :expected-missing
          :descriptor-relative-c17-publication-provenance
          :return-fact :provider-return-code}
         {:operation :fchmod :reason :descriptor-chmod-failed
          :expected-id "B13-SCHEMA"
          :expected-missing :exact-descriptor-relative-c17-bundle
          :return-fact :provider-return-code}
         {:operation :fsync :reason :descriptor-sync-failed
          :expected-id "B13-PROVENANCE"
          :expected-missing
          :descriptor-relative-c17-publication-provenance
          :return-fact :provider-return-code}
         {:operation :inventory :reason :directory-reopen-failed
          :expected-id "B13-PROVENANCE"
          :expected-missing
          :descriptor-relative-c17-publication-provenance
          :return-fact :provider-return-code}
         {:operation :inventory :reason :directory-stream-close-failed
          :expected-id "B13-PROVENANCE"
          :expected-missing
          :descriptor-relative-c17-publication-provenance
          :return-fact :provider-return-code}
         {:operation :read-file :reason :file-readback-failed
          :expected-id "B13-HASH"
          :expected-missing
          :descriptor-relative-c17-publication-content
          :return-fact :provider-return-code}
         {:operation :validate-bundle :reason :invalid-file-set
          :expected-id "B13-SCHEMA"
          :expected-missing :exact-descriptor-relative-c17-bundle}
         {:operation :commit :reason :destination-collision
          :expected-id "B2-MANIFEST"
          :expected-missing :exclusive-no-clobber-c17-publication
          :return-fact :rename-return-code}]]
    (doseq [{:keys [operation reason expected-id expected-missing
                    return-fact]}
            cases]
      (let [raw-data
            (cond->
             {:gravity.darwin-publication/error true
              :provider :gravity/darwin-descriptor-publication
              :provider-version 1 :operation operation :reason reason
              :errno 5 :logical-path "program.c"
              :expected-byte-count 4 :observed-byte-count 3
              :expected-mode 0644 :observed-mode 0755
              :untrusted-secret "must-not-cross-boundary"}
              (= reason :native-access-disabled)
              (assoc :native-access-enabled? false)

              (= reason :destination-exists)
              (assoc :output-collision? true)

              return-fact (assoc :return-code -1))
            diagnostic
            (diagnostic-data
             #(provider-call!
               "/tmp/provider-mapping.gravity" :stage
               (fn []
                 (throw (ex-info "synthetic raw provider failure"
                                 raw-data)))))
            facts (:facts diagnostic)]
        (is (= expected-id (:id diagnostic)) [reason diagnostic])
        (is (= expected-missing (:missing-fact diagnostic))
            [reason diagnostic])
        (is (= reason (:bounded-reason facts)) [reason facts])
        (is (= operation (:tool-step facts)) [reason facts])
        (when (= reason :native-access-disabled)
          (is (false? (:native-access-enabled? facts)) facts))
        (when (= reason :destination-exists)
          (is (true? (:output-collision? facts)) facts))
        (is (= [4 3 "0644" "0755"]
               ((juxt :expected-byte-count :observed-byte-count
                      :expected-mode :observed-mode)
                facts))
            [reason facts])
        (when return-fact
          (is (= -1 (get facts return-fact)) [reason facts]))
        (is (= (boolean (= return-fact :rename-return-code))
               (contains? facts :rename-return-code))
            [reason facts])
        (is (= (boolean (= return-fact :provider-return-code))
               (contains? facts :provider-return-code))
            [reason facts])
        (is (not (contains? diagnostic
                            :gravity.darwin-publication/error))
            [reason diagnostic])
        (is (not (str/includes? (pr-str diagnostic)
                                "must-not-cross-boundary"))
            [reason diagnostic])))
    (let [material {:file-records {} :sidecars {}}
          exact-invalid
          {:status :invalid
           :actual-output-directory "/tmp/provider-mapping-bundle"
           :file-records {}
           :publisher-evidence {}
           :mode-policy {}}
          mismatched
          (assoc exact-invalid :file-records {"unexpected" {}})
          envelope-diagnostic
          (diagnostic-data
           #(canonical-receipt nil material
                               "/tmp/provider-mapping.gravity"))
          record-diagnostic
          (diagnostic-data
           #(canonical-receipt mismatched material
                               "/tmp/provider-mapping.gravity"))
          value-diagnostic
          (diagnostic-data
           #(canonical-receipt exact-invalid material
                               "/tmp/provider-mapping.gravity"))]
      (is (= ["B13-SCHEMA"
              :canonical-darwin-publication-receipt-envelope]
             ((juxt :id :missing-fact) envelope-diagnostic))
          envelope-diagnostic)
      (is (= ["B13-HASH"
              :content-bound-darwin-publication-file-records]
             ((juxt :id :missing-fact) record-diagnostic))
          record-diagnostic)
      (is (= ["B13-SCHEMA"
              :canonical-darwin-publication-receipt-values]
             ((juxt :id :missing-fact) value-diagnostic))
          value-diagnostic))))

(deftest authenticated-b2-gate-b-incomplete-cleanup-is-bounded
  (let [abort-after-failure!
        (authenticated-b2-gate-b-private-var
         'p15-s23-b2-c17-gate-b-abort-after-failure!)
        capture
        (fn [operation]
          (try
            (operation)
            ::unexpected-success
            (catch Throwable error error)))
        primary
        (capture
         #(bootstrap/p15-s23-c-backend-fail!
           "B13-HASH" "/tmp/cleanup.gravity" {}
           {:missing-fact :synthetic-primary-hash-failure}))
        after-abort
        (with-redefs
          [darwin-publication/abort-staged-bundle!
           (fn [_]
             {:status :aborted :published? false
              :cleanup-complete? false :residue-possible? true})]
          (capture
           #(abort-after-failure!
             (Object.) "/tmp/cleanup.gravity" primary)))
        after-containment
        (capture
         #(bootstrap/p15-s23-c-backend-contain-exception!
           "/tmp/cleanup.gravity" :synthetic-outer-boundary
           after-abort))]
    (doseq [observed [after-abort after-containment]]
      (is (= "B13-PROVENANCE" (:id (ex-data observed)))
          (ex-data observed))
      (is (= :complete-descriptor-relative-c17-publication-cleanup
             (get-in (ex-data observed) [:facts :missing-fact])))
      (is (false? (get-in (ex-data observed)
                          [:facts :cleanup-complete?])))
      (is (true? (get-in (ex-data observed)
                         [:facts :residue-possible?])))
      (is (= "B13-HASH"
             (get-in (ex-data observed)
                     [:facts :primary-failure-rule])))
      (is (= (:diagnostic-id (ex-data primary))
             (get-in (ex-data observed)
                     [:facts :primary-diagnostic-id]))))
    (is (= 1 (count (.getSuppressed ^Throwable after-abort))))
    (is (zero? (count (.getSuppressed ^Throwable after-containment))))
    (doseq [cleanup
            [nil
             {:cleanup-complete? true :residue-possible? false}
             {:status :aborted :published? false
              :cleanup-complete? false :residue-possible? false}
             {:status :already-committed :published? true
              :cleanup-applicable? false :native-calls 0}]]
      (let [observed
            (with-redefs
              [darwin-publication/abort-staged-bundle!
               (fn [_] cleanup)]
              (capture
               #(abort-after-failure!
                 (Object.) "/tmp/cleanup.gravity" primary)))]
        (is (= "B13-PROVENANCE" (:id (ex-data observed)))
            [cleanup (ex-data observed)])
        (is (true? (get-in (ex-data observed)
                           [:facts :residue-possible?]))
            [cleanup (ex-data observed)])))
    (let [observed
          (with-redefs
            [darwin-publication/abort-staged-bundle!
             (fn [_]
               {:status :already-aborted :published? false
                :cleanup-complete? true :residue-possible? false
                :native-calls 0})]
            (capture
             #(abort-after-failure!
               (Object.) "/tmp/cleanup.gravity" primary)))]
      (is (identical? primary observed)))
    (let [primary-interrupt (InterruptedException. "primary interrupt")
          cleanup-fatal (OutOfMemoryError. "fatal cleanup")
          _ (Thread/interrupted)
          observed
          (with-redefs
            [darwin-publication/abort-staged-bundle!
             (fn [_] (throw cleanup-fatal))]
            (capture
             #(abort-after-failure!
               (Object.) "/tmp/cleanup.gravity" primary-interrupt)))
          interrupted? (.isInterrupted (Thread/currentThread))]
      (Thread/interrupted)
      (is (identical? cleanup-fatal observed))
      (is (true? interrupted?))
      (is (some #(identical? primary-interrupt %)
                (.getSuppressed ^Throwable cleanup-fatal))))
    (let [primary-fatal (AssertionError. "fatal primary")
          cleanup-interrupt
          (java.io.InterruptedIOException. "cleanup interrupt")
          _ (Thread/interrupted)
          observed
          (with-redefs
            [darwin-publication/abort-staged-bundle!
             (fn [_] (throw cleanup-interrupt))]
            (capture
             #(abort-after-failure!
               (Object.) "/tmp/cleanup.gravity" primary-fatal)))
          interrupted? (.isInterrupted (Thread/currentThread))]
      (Thread/interrupted)
      (is (identical? primary-fatal observed))
      (is (true? interrupted?))
      (is (some #(identical? cleanup-interrupt %)
                (.getSuppressed ^Throwable primary-fatal))))
    (let [gate-b-artifact!
          (authenticated-b2-gate-b-private-var
           'p15-s23-stage2-b2-c17-gate-b-artifact!)
          pre-effect-gate!
          (authenticated-b2-gate-b-private-var
           'p15-s23-b2-c17-gate-b-pre-effect-gate!)
          output-preflight!
          (authenticated-b2-gate-b-private-var
           'p15-s23-b2-c17-gate-b-output-preflight!)
          toolchain-transaction!
          (authenticated-b2-gate-b-private-var
           'p15-s23-b2-c17-gate-b-toolchain-transaction!)
          opened-context (Object.)
          aborts (atom [])
          fatal (AssertionError. "fatal first post-open operation")
          observed
          (with-redefs-fn
            {pre-effect-gate!
             (fn [& _]
               {:options {:output-directory "/tmp/never-observed"}
                :gate-a-contextual-report {}})
             output-preflight! (fn [& _] opened-context)
             toolchain-transaction! (fn [& _] (throw fatal))
             #'darwin-publication/abort-staged-bundle!
             (fn [context]
               (swap! aborts conj context)
               {:status :aborted :published? false
                :cleanup-complete? true :residue-possible? false})}
            #(capture
              (fn []
                (gate-b-artifact!
                 {} {} {:source-path "/tmp/post-open.gravity"} {}))))]
      (is (identical? fatal observed))
      (is (= [opened-context] @aborts)))))

