;; Internal experimental binary ordering slice.  The language-wide arity and
;; mixed-numeric policy remain undecided; these tests credit only exact ordered
;; integer predicates that C14 proves fit the signed-i64 C17 carrier.

(def ^:private authenticated-binary-integer-order-cases
  [{:label :lt-true :operator '< :source-operation :integer-lt
    :left "-9223372036854775808" :right "9223372036854775807"
    :expected 9 :extension ".gravity" :c-token "<"}
   {:label :lt-equal-false :operator '< :source-operation :integer-lt
    :left "7" :right "7" :expected 3 :extension ".qst" :c-token "<"}
   {:label :lte-equal-true :operator '<= :source-operation :integer-lte
    :left "7" :right "7" :expected 9 :extension ".gravity" :c-token "<="}
   {:label :lte-false :operator '<= :source-operation :integer-lte
    :left "9223372036854775807" :right "-9223372036854775808"
    :expected 3 :extension ".qst" :c-token "<="}
   {:label :gt-true :operator '> :source-operation :integer-gt
    :left "9223372036854775807" :right "-9223372036854775808"
    :expected 9 :extension ".gravity" :c-token ">"}
   {:label :gt-equal-false :operator '> :source-operation :integer-gt
    :left "7" :right "7" :expected 3 :extension ".qst" :c-token ">"}
   {:label :gte-equal-true :operator '>= :source-operation :integer-gte
    :left "7" :right "7" :expected 9 :extension ".gravity" :c-token ">="}
   {:label :gte-false :operator '>= :source-operation :integer-gte
    :left "-9223372036854775808" :right "9223372036854775807"
    :expected 3 :extension ".qst" :c-token ">="}])

(defn- authenticated-binary-integer-order-source
  [operator left right]
  (closed-pure-source-with-main
   (str "(let [x " left " y " right "] "
        "(if (" operator " x y) 9 3))")
   {:exports '[main]}))

(def ^:private authenticated-binary-integer-order-composite-source
  (closed-pure-source-with-main
   "(do (< 1 2) (<= 2 2) (> 3 2) (>= 4 4) 9)"
   {:exports '[main]}))

(defn- authenticated-binary-integer-order-gate-a-row
  [root case]
  (let [source
        (authenticated-binary-integer-order-source
         (:operator case) (:left case) (:right case))
        file (.resolve root (str (name (:label case)) (:extension case)))
        _ (spit (.toFile file) source)
        path (.toString
              (.toRealPath file (make-array java.nio.file.LinkOption 0)))
        upstream
        (authenticated-binary-integer-comparison-upstream path source)
        artifact
        (bootstrap/p15-s23-stage2-b2-c17-artifact-from-c11!
         (:c11 upstream) (:checked-core upstream) (:context upstream))]
    (assoc case :source source :path path
           :upstream upstream :artifact artifact)))

(defn- authenticated-binary-integer-order-composite-row
  [root extension]
  (let [file (.resolve root (str "all-ordering" extension))
        _ (spit (.toFile file)
                authenticated-binary-integer-order-composite-source)
        path (.toString
              (.toRealPath file (make-array java.nio.file.LinkOption 0)))
        upstream
        (authenticated-binary-integer-comparison-upstream
         path authenticated-binary-integer-order-composite-source)
        artifact
        (bootstrap/p15-s23-stage2-b2-c17-artifact-from-c11!
         (:c11 upstream) (:checked-core upstream) (:context upstream))]
    {:path path :upstream upstream :artifact artifact}))

(def ^:private authenticated-binary-integer-order-gate-a-proof
  (delay
    (with-temp-directory
      "gravity-authenticated-integer-order-left-"
      (fn [left-root]
        (with-temp-directory
          "gravity-authenticated-integer-order-right-"
          (fn [right-root]
            (let [before
                  (bootstrap/p15-s23-b2-c17-gate-b-tool-execution-snapshot)
                  rows
                  (mapv
                   #(authenticated-binary-integer-order-gate-a-row
                     left-root %)
                   authenticated-binary-integer-order-cases)
                  composite-left
                  (authenticated-binary-integer-order-composite-row
                   left-root ".gravity")
                  composite-right
                  (authenticated-binary-integer-order-composite-row
                   right-root ".qst")
                  verification
                  (bootstrap/p15-s23-stage2-b2-c17-verification-report
                   (:artifact composite-left)
                   (get-in composite-left [:upstream :checked-core])
                   (get-in composite-left [:upstream :context]))
                  after
                  (bootstrap/p15-s23-b2-c17-gate-b-tool-execution-snapshot)]
              {:rows rows
               :composite-left composite-left
               :composite-right composite-right
               :verification verification
               :before before :after after})))))))

(deftest authenticated-binary-integer-ordering-reaches-gate-a-authentically
  (let [{:keys [rows composite-left composite-right verification
                before after]}
        @authenticated-binary-integer-order-gate-a-proof
        expected-operations
        #{:integer-lt :integer-lte :integer-gt :integer-gte}]
    (is (= before after))
    (is (= [:passed :passed :passed :passed :passed :passed]
           ((juxt :fresh-c11 :fresh-c13 :fresh-c14 :fresh-b1
                  :gravity-b2-source-replay :independent-c-reconstruction)
            verification)))
    (is (= :passed (:status verification)))
    (doseq [{:keys [label operator source-operation expected c-token
                    extension upstream artifact]} rows]
      (let [core (:checked-core upstream)
            node
            (first (filter #(= source-operation (:source-operation %))
                           (:core-nodes core)))
            operations
            (bootstrap/p15-s23-c11-mir-operation-sequence
             (get-in upstream [:c11 :mir-module]))
            operation
            (first (filter #(= source-operation (:opcode %)) operations))
            [left-id right-id] (:operands operation)
            operation-by-id (into {} (map (juxt :op-id identity)) operations)
            records (:operation-records artifact)
            record
            (first (filter #(= source-operation (:mir-opcode %)) records))
            record-by-id
            (into {} (map (juxt :mir-operation-id identity)) records)
            expected-expression
            (str "(" (get-in record-by-id [left-id :c-value])
                 " " c-token " "
                 (get-in record-by-id [right-id :c-value])
                 " ? INT64_C(1) : INT64_C(0))")
            proof (get-in node [:safety :proof])
            proof-entries
            (get-in artifact [:proof-to-c-assumption-map :entries])
            ordering-entries
            (filterv #(= :defined-signed-i64-ordering
                         (:assumption %))
                     proof-entries)]
        (is (= [:comparison source-operation :gravity/bool 2]
               ((juxt :kind :source-operation :type
                      #(count (:operands %))) node)) label)
        (is (= operator (get-in node [:attributes :primitive])) label)
        (is (= :left-to-right
               (get-in node [:attributes :evaluation-order])) label)
        (is (= [:gravity/integer :gravity/integer]
               (get-in node [:attributes :operand-types])) label)
        (is (= :proof-required
               (get-in node [:attributes :numeric-mode])) label)
        (is (= :integer-exact
               (get-in node [:attributes :mathematical-mode])) label)
        (is (= :exact-integer-ordering
               (get-in node [:attributes :numeric-semantics])) label)
        (is (= :not-applicable
               (get-in node [:attributes :overflow])) label)
        (is (= :proven-safe (get-in node [:safety :outcome])) label)
        (is (= :exact-integer-ordering
               (get-in node [:safety :basis]) (:basis proof)) label)
        (is (= (:operands node) (:operand-node-ids proof)) label)
        (is (= [source-operation source-operation :gravity/bool]
               ((juxt :opcode :source-operation :type) operation)) label)
        (is (= (:operands node) (:operands operation)) label)
        (is (= [:gravity/integer :gravity/integer]
               (mapv #(get-in operation-by-id [% :type])
                     [left-id right-id])) label)
        (is (empty? (:effects operation)) label)
        (is (empty? (:capabilities operation)) label)
        (is (= expected (:semantic-result artifact)
               (:expected-exit-code artifact)) label)
        (is (= expected-expression (:c-expression record)) label)
        (is (= [{:assumption :defined-signed-i64-ordering
                 :evidence
                 :authenticated-ordered-two-integer-operands-and-boolean-result
                 :c-site :generated-integer-ordering-expressions
                 :outcome :proven-safe}]
               ordering-entries)
            label)
        (is (not-any? #(= :defined-signed-i64-equality (:assumption %))
                      proof-entries)
            label)
        (is (nil? (bootstrap/p15-s23-b3-llvm-operation-rejection
                   operations operation)) label)
        (is (contains? #{".gravity" ".qst"} extension) label)
        (doseq [key [:whole-b2? :public? :release? :self-hosted?]]
          (is (false? (get artifact key)) [label key]))))
    (doseq [[source-operation grouped]
            (group-by :source-operation rows)]
      (is (= #{".gravity" ".qst"} (set (map :extension grouped)))
          source-operation))
    (let [left (:artifact composite-left)
          right (:artifact composite-right)
          left-upstream (:upstream composite-left)
          right-upstream (:upstream composite-right)
          left-operations
          (bootstrap/p15-s23-c11-mir-operation-sequence
           (get-in left-upstream [:c11 :mir-module]))]
      (is (= expected-operations
             (set (keep #(when (contains? expected-operations (:opcode %))
                          (:opcode %))
                        left-operations))))
      (is (= (:artifact-id (:checked-core left-upstream))
             (:artifact-id (:checked-core right-upstream))))
      (is (= (get-in left-upstream [:c11 :mir-id])
             (get-in right-upstream [:c11 :mir-id])))
      (is (= (:semantic-id left) (:semantic-id right)))
      (is (= (:artifact-id left) (:artifact-id right)))
      (is (not= (:actual-path-binding-id left)
                (:actual-path-binding-id right)))
      (is (= (:path composite-left)
             (get-in left [:actual-path-provenance :source])))
      (is (= (:path composite-right)
             (get-in right [:actual-path-provenance :source]))))))

(deftest authenticated-binary-integer-ordering-rejects-tamper-and-bad-input
  (let [{:keys [rows before after]}
        @authenticated-binary-integer-order-gate-a-proof
        representative (first rows)
        upstream (:upstream representative)
        core (:checked-core upstream)
        context (:context upstream)
        module (get-in upstream [:c11 :mir-module])
        operations (bootstrap/p15-s23-c11-mir-operation-sequence module)
        operation (first (filter #(= :integer-lt (:opcode %)) operations))
        operation-id (:op-id operation)
        update-core
        (fn [candidate transform]
          (update candidate :core-nodes
                  (fn [nodes]
                    (mapv (fn [node]
                            (if (= operation-id (:node-id node))
                              (transform node)
                              node))
                          nodes))))
        primitive-core
        (update-core core #(assoc-in % [:attributes :primitive] '<=))
        numeric-mode-core
        (update-core
         core #(assoc-in % [:attributes :numeric-mode] :unchecked))
        mathematical-mode-core
        (update-core
         core #(assoc-in % [:attributes :mathematical-mode] :fast))
        safety-core
        (update-core core #(assoc-in % [:safety :basis] :forged-ordering))
        reversed-core
        (update-core
         core
         #(-> %
              (update :operands (comp vec reverse))
              (update-in [:safety :proof :operand-node-ids]
                         (comp vec reverse))))
        reversed-module
        (c11-update-operation
         module operation-id #(update % :operands (comp vec reverse)))
        result-type-module
        (c11-update-operation
         module operation-id #(assoc % :type :gravity/integer))
        arity-module
        (c11-update-operation
         module operation-id #(assoc % :operands [(first (:operands %))]))
        mutation-data
        [{:label :primitive
          :data (c11-raw-diagnostic module primitive-core context)
          :id "C11-TYPE"
          :missing :exact-binary-integer-order-comparison-schema}
         {:label :numeric-mode
          :data (c11-raw-diagnostic module numeric-mode-core context)
          :id "C11-TYPE"
          :missing :exact-binary-integer-order-comparison-schema}
         {:label :mathematical-mode
          :data (c11-raw-diagnostic module mathematical-mode-core context)
          :id "C11-TYPE"
          :missing :exact-binary-integer-order-comparison-schema}
         {:label :safety
          :data (c11-raw-diagnostic module safety-core context)
          :id "C11-SAFETY"
          :missing :authenticated-pure-integer-order-comparison-proof}
         {:label :ordered-operands
          :data (c11-raw-diagnostic reversed-module reversed-core context)
          :id "C11-SAFETY"
          :missing :id-indexed-authenticated-safety-proof-certificates}
         {:label :result-type
          :data (c11-raw-diagnostic result-type-module core context)
          :id "C11-TYPE"
          :missing :exact-binary-integer-order-comparison-schema}
         {:label :arity
          :data (c11-raw-diagnostic arity-module core context)
          :id "C11-MODULE"
          :missing :checked-core-operation-parity}]
        opcode-mutation-data
        (mapv
         (fn [{:keys [label source-operation upstream]}]
           (let [candidate-module (get-in upstream [:c11 :mir-module])
                 candidate-operations
                 (bootstrap/p15-s23-c11-mir-operation-sequence
                  candidate-module)
                 candidate
                 (first (filter #(= source-operation (:opcode %))
                                candidate-operations))]
             {:label label
              :data
              (c11-raw-diagnostic
               (c11-update-operation
                candidate-module (:op-id candidate)
                #(assoc % :opcode :integer-eq))
               (:checked-core upstream) (:context upstream))}))
         (take-nth 2 rows))
        c14-source
        (slurp bootstrap/p15-s23-c14-source-relative-path)
        c14-plan
        (bootstrap/p15-s23-stage2-compiler-artifact-plan
         (:emitter
          (bootstrap/c-backend-stage2-plan-emitter-source-rule!
           bootstrap/p15-s23-c14-source-relative-path :c))
         bootstrap/p15-s23-c14-source-relative-path c14-source)
        c14-invoke
        (fn [candidate operations-by-id seen]
          (bootstrap/p15-s23-stage2-runtime-execute-function
           {:engine :integer-order-c14-hostile-validator-test
            :compiler-artifact-plan? true}
           c14-plan 'c14-c-operation-valid?
           [candidate operations-by-id seen]))
        b2-source
        (slurp bootstrap/p15-s23-b2-c17-source-relative-path)
        b2-plan
        (bootstrap/p15-s23-stage2-compiler-artifact-plan
         (:emitter
          (bootstrap/c-backend-stage2-plan-emitter-source-rule!
           bootstrap/p15-s23-b2-c17-source-relative-path :c))
         bootstrap/p15-s23-b2-c17-source-relative-path b2-source)
        b2-invoke
        (fn [candidate candidate-operations operation-index block-order]
          (bootstrap/p15-s23-stage2-runtime-execute-function
           {:engine :integer-order-b2-hostile-validator-test
            :compiler-artifact-plan? true}
           b2-plan 'b2-operation-reason
           [candidate candidate-operations operation-index block-order]))
        compiled-validator-results
        (mapv
         (fn [{:keys [label source-operation upstream]}]
           (let [candidate-module (get-in upstream [:c11 :mir-module])
                 function (get-in candidate-module [:functions 'main])
                 block-order
                 (bootstrap/p15-s23-b3-llvm-block-order
                  candidate-module function)
                 candidate-operations
                 (bootstrap/p15-s23-b3-llvm-operation-sequence
                  function block-order)
                 candidate
                 (first (filter #(= source-operation (:opcode %))
                                candidate-operations))
                 candidate-id (:op-id candidate)
                 operations-by-id
                 (into {} (map (juxt :op-id identity))
                       candidate-operations)
                 operation-index
                 (into {}
                       (map-indexed
                        (fn [index item] [(:op-id item) index]))
                       candidate-operations)
                 seen
                 (set (map :op-id
                           (take-while #(not= candidate-id (:op-id %))
                                       candidate-operations)))
                 mutations
                 [{:kind :source-operation
                   :candidate (assoc candidate
                                     :source-operation :integer-eq)
                   :c14-reason :integer-order-source-operation
                   :b2-reason :source-operation-opcode-parity}
                  {:kind :arity
                   :candidate
                   (assoc candidate :operands [(first (:operands candidate))])
                   :c14-reason :integer-order-requires-two-operands
                   :b2-reason :integer-order-arity}
                  {:kind :result-type
                   :candidate (assoc candidate :type :gravity/integer)
                   :c14-reason :integer-order-result-type
                   :b2-reason :integer-order-result-type}
                  {:kind :dominance
                   :candidate
                   (assoc candidate
                          :operands
                          [candidate-id (second (:operands candidate))])
                   :c14-reason :integer-order-left-dominance
                   :b2-reason
                   :integer-order-prior-definition-or-dominance}]]
             {:label label
              :genuine-c14
              (c14-invoke candidate operations-by-id seen)
              :genuine-b2
              (b2-invoke candidate candidate-operations
                         operation-index block-order)
              :mutations
              (mapv
               (fn [{:keys [candidate] :as mutation}]
                 (assoc
                  mutation
                  :compiled-c14
                  (c14-invoke candidate operations-by-id seen)
                  :host-c14
                  (bootstrap/p15-s23-c14-c-operation-rejection
                   candidate-operations candidate)
                  :compiled-b2
                  (b2-invoke candidate candidate-operations
                             operation-index block-order)))
               mutations)}))
         (take-nth 2 rows))
        source-for
        (fn [body] (closed-pure-source-with-main body {:exports '[main]}))
        bad-cases
        (mapcat
         (fn [{:keys [operator source-operation]}]
           (let [operator-text (str operator)]
             [{:label [source-operation :zero]
               :body (str "(" operator-text ")")
               :id "L2-BUILTIN-ARITY"
               :stage :core-language-semantics
               :missing :at-least-two-comparison-arguments}
              {:label [source-operation :unary]
               :body (str "(" operator-text " 1)")
               :id "L2-BUILTIN-ARITY"
               :stage :core-language-semantics
               :missing :at-least-two-comparison-arguments}
              {:label [source-operation :nary]
               :body (str "(" operator-text " 1 2 3)")
               :id "C6-LOWERING-GAP" :stage :core-lowering
               :missing :bounded-binary-integer-order-comparison}
              {:label [source-operation :mixed]
               :body (str "(" operator-text " true 1)")
               :id "C7-TYPE-MISMATCH" :stage :type-check
               :missing :binary-integer-order-comparison-operands}]))
         (take-nth 2 authenticated-binary-integer-order-cases))
        reject-before
        (bootstrap/p15-s23-b2-c17-gate-b-tool-execution-snapshot)
        bad-results
        (vec
         (for [{:keys [label body] :as case} bad-cases
               extension [".gravity" ".qst"]]
           (assoc
            case :extension extension
            :data
            (diagnostic-data
             #(bootstrap/p15-s23-stage2-b2-c17-gate-b-source-artifact!
               (str "integer-order-" (name (first label)) "-"
                    (name (second label)) extension)
               (source-for body))))))
        below
        (diagnostic-data
         #(bootstrap/p15-s23-stage2-b2-c17-gate-b-source-artifact!
           "integer-order-below-i64.qst"
           (authenticated-binary-integer-order-source
            '< "-9223372036854775809" "0")))
        above
        (diagnostic-data
         #(bootstrap/p15-s23-stage2-b2-c17-gate-b-source-artifact!
           "integer-order-above-i64.gravity"
           (authenticated-binary-integer-order-source
            '>= "0" "9223372036854775808")))
        reject-after
        (bootstrap/p15-s23-b2-c17-gate-b-tool-execution-snapshot)]
    (is (= before after reject-before reject-after))
    (doseq [{:keys [label data id missing]} mutation-data]
      (is (= id (:id data)) [label data])
      (is (= missing (:missing-fact data)) [label data]))
    (doseq [{:keys [label data]} opcode-mutation-data]
      (is (= "C11-MODULE" (:id data)) [label data])
      (is (= :checked-core-operation-parity (:missing-fact data))
          [label data]))
    (doseq [{:keys [label genuine-c14 genuine-b2 mutations]}
            compiled-validator-results]
      (is (true? genuine-c14) [label :genuine-c14 genuine-c14])
      (is (nil? genuine-b2) [label :genuine-b2 genuine-b2])
      (doseq [{:keys [kind compiled-c14 host-c14 compiled-b2
                      c14-reason b2-reason]}
              mutations]
        (is (false? compiled-c14)
            [label kind :compiled-c14 compiled-c14])
        (is (= c14-reason host-c14)
            [label kind :host-c14 host-c14])
        (is (= b2-reason compiled-b2)
            [label kind :compiled-b2 compiled-b2])))
    (doseq [{:keys [label id stage missing data]} bad-results]
      (is (= id (:id data) (:rule data)) [label data])
      (is (= stage (:stage data)) [label data])
      (is (= missing (:missing-fact data)) [label data])
      (is (not (str/includes? (pr-str data) "NumberFormatException"))
          [label data]))
    (doseq [label (set (map :label bad-results))]
      (let [pair (filter #(= label (:label %)) bad-results)]
        (is (= 2 (count pair)) label)
        (is (apply = (map #(get-in % [:data :diagnostic-id]) pair)) label)
        (is (apply = (map #(get-in % [:data :facts]) pair)) label)))
    (doseq [[label data] [[:below below] [:above above]]]
      (is (= "C14-UNSUPPORTED" (:id data) (:rule data)) [label data])
      (is (= :c14-target-lowering (:stage data)) [label data])
      (is (= :bounded-scalar-constant-payload (:missing-fact data))
          [label data])
      (is (not (str/includes? (pr-str data) "NumberFormatException"))
          [label data])
      (is (not (str/includes? (pr-str data) "ArithmeticException"))
          [label data]))))

(def ^:private authenticated-binary-integer-order-gate-b-proof
  (delay
    (authenticated-b2-gate-b-with-home-temp-directory
      "gravity-authenticated-integer-order-native-"
      (fn [root]
        (let [selected-labels
              [:lt-true :lte-false :gt-true :gte-false]
              row-by-label
              (into {} (map (juxt :label identity))
                    (:rows @authenticated-binary-integer-order-gate-a-proof))
              before
              (bootstrap/p15-s23-b2-c17-gate-b-tool-execution-snapshot)
              runs
              (loop [labels selected-labels
                     result []
                     previous before]
                (if (empty? labels)
                  result
                  (let [label (first labels)
                        row (get row-by-label label)
                        options
                        (if (empty? result)
                          {:output-directory
                           (.toString (.resolve root "ordering-bundle"))}
                          {})
                        artifact
                        (bootstrap/p15-s23-stage2-b2-c17-gate-b-artifact-from-c11!
                         (get-in row [:upstream :c11])
                         (get-in row [:upstream :checked-core])
                         (get-in row [:upstream :context]) options)
                        snapshot
                        (bootstrap/p15-s23-b2-c17-gate-b-tool-execution-snapshot)]
                    (recur (rest labels)
                           (conj result
                                 {:label label :row row :artifact artifact
                                  :before previous :after snapshot})
                           snapshot))))]
          {:runs runs
           :names
           (set (seq (.list (.toFile (.resolve root "ordering-bundle")))))})))))

(deftest authenticated-binary-integer-ordering-runs-real-c17-every-predicate
  (let [{:keys [runs names]}
        @authenticated-binary-integer-order-gate-b-proof]
    (is (= 4 (count runs)))
    (is (= #{{:label :lt-true :expected 9}
             {:label :lte-false :expected 3}
             {:label :gt-true :expected 9}
             {:label :gte-false :expected 3}}
           (set (map (fn [{:keys [label row]}]
                       {:label label :expected (:expected row)})
                     runs))))
    (doseq [{:keys [label row artifact before after]} runs]
      (let [expected (:expected row)
            process (get-in artifact [:toolchain-evidence :process-evidence])
            ordering-entries
            (filterv #(= :defined-signed-i64-ordering
                         (:assumption %))
                     (get-in artifact
                             [:gate-a-artifact
                              :proof-to-c-assumption-map :entries]))]
        (is (= 20 (- (:total after) (:total before))) label)
        (is (= {:expected-exit-code expected
                :observed-exit-code expected
                :stdout-byte-count 0 :stderr-byte-count 0 :matched? true}
               process) label)
        (is (= [expected expected]
               ((juxt #(get-in % [:c18-record :semantic-bindings
                                  :expected-result])
                      #(get-in % [:c18-record :semantic-bindings
                                  :observed-result]))
                artifact)) label)
        (is (= (if (= :lt-true label)
                 :published-atomically-after-final-verification
                 :ephemeral-conformance-artifacts)
               (get-in artifact [:publication-receipt :status]))
            label)
        (is (= [{:assumption :defined-signed-i64-ordering
                 :evidence
                 :authenticated-ordered-two-integer-operands-and-boolean-result
                 :c-site :generated-integer-ordering-expressions
                 :outcome :proven-safe}]
               ordering-entries)
            label)
        (doseq [key [:whole-b2? :public? :release? :self-hosted?]]
          (is (false? (get artifact key)) [label key]))))
    (is (= #{"program.c" "program.h" "program.o" "program"
             "manifest.edn" "provenance.edn" "conformance.edn"}
           names))))

;; The matching LLVM slice remains internal and experimental.  These tests
;; credit only authenticated binary signed-i64 comparisons through the pinned
;; Gravity B3 source and the existing arm64 macOS Clang boundary.

(def ^:private authenticated-binary-integer-llvm-cases
  [{:label :eq-true :operator '= :source-operation :integer-eq
    :left "-9223372036854775808" :right "-9223372036854775808"
    :expected true :extension ".gravity" :predicate "eq"}
   {:label :eq-false :operator '= :source-operation :integer-eq
    :left "-9223372036854775808" :right "9223372036854775807"
    :expected false :extension ".qst" :predicate "eq"}
   {:label :lt-true :operator '< :source-operation :integer-lt
    :left "-9223372036854775808" :right "9223372036854775807"
    :expected true :extension ".gravity" :predicate "slt"}
   {:label :lt-equal-false :operator '< :source-operation :integer-lt
    :left "7" :right "7" :expected false :extension ".qst"
    :predicate "slt"}
   {:label :lte-equal-true :operator '<= :source-operation :integer-lte
    :left "7" :right "7" :expected true :extension ".gravity"
    :predicate "sle"}
   {:label :lte-false :operator '<= :source-operation :integer-lte
    :left "9223372036854775807" :right "-9223372036854775808"
    :expected false :extension ".qst" :predicate "sle"}
   {:label :gt-true :operator '> :source-operation :integer-gt
    :left "9223372036854775807" :right "-9223372036854775808"
    :expected true :extension ".gravity" :predicate "sgt"}
   {:label :gt-equal-false :operator '> :source-operation :integer-gt
    :left "7" :right "7" :expected false :extension ".qst"
    :predicate "sgt"}
   {:label :gte-equal-true :operator '>= :source-operation :integer-gte
    :left "7" :right "7" :expected true :extension ".gravity"
    :predicate "sge"}
   {:label :gte-false :operator '>= :source-operation :integer-gte
    :left "-9223372036854775808" :right "9223372036854775807"
    :expected false :extension ".qst" :predicate "sge"}])

(defn- authenticated-binary-integer-llvm-source
  [{:keys [operator left right]}]
  (closed-pure-source-with-main
   (str "(let [x " left " y " right "] (" operator " x y))")
   {:exports '[main]}))

(defn- authenticated-binary-integer-closed-plan
  [instruction]
  {:entrypoint 'main
   :source {:path "authenticated-binary-integer-closed-plan.gravity"}
   :functions
   {'main {:arity 0 :params [] :instructions [instruction]}}})

(deftest authenticated-reference-runtime-compares-binary-integers
  (let [runtime-rule
        (bootstrap/c-backend-stage2-runtime-source-rule!
         "authenticated-reference-integer-comparisons.gravity" :llvm)
        runtime-plan (:runtime-artifact-plan runtime-rule)
        runtime-contract
        (get-in runtime-rule
                [:runtime-contract-definitions
                 'p15-s23-reference-runtime-contract])
        execute
        (fn [plan]
          (bootstrap/p15-s23-stage2-runtime-execute-function
           {:engine :authenticated-reference-integer-comparison-test}
           runtime-plan
           bootstrap/p15-s23-stage2-runtime-artifact-closed-plan-function
           [plan]))]
    (is (true?
         (:checked-core-binary-integer-comparison-admission?
          runtime-contract)))
    (is (= '#{= < <= > >=}
           (:checked-core-binary-integer-comparison-operations
            runtime-contract)))
    (is (= bootstrap/p15-s23-stage2-runtime-artifact-expected-artifact-hash
           (:runtime-artifact-hash runtime-rule)))
    (is (= 328
           (get-in runtime-rule
                   [:runtime-contract-validation-record :operation-count])))
    (doseq [{:keys [label operator left right expected]}
            authenticated-binary-integer-llvm-cases]
      (let [plan
            (authenticated-binary-integer-closed-plan
             {:op :builtin-call :function operator
              :args [{:op :literal :value (bigint left)}
                     {:op :literal :value (bigint right)}]})
            validation
            (bootstrap/p15-s23-closed-runtime-plan-validation!
             (:path (:source plan)) :llvm plan)
            execution (execute plan)]
        (is (= :complete (:status validation)) label)
        (is (= expected (:entrypoint-result execution)) label)
        (is (= "" (:stdout execution)) label)))
    (let [large-left (bigint "9223372036854775808")
          large-right (bigint "9223372036854775809")
          local-plan
          (authenticated-binary-integer-closed-plan
           {:op :let
            :bindings
            [{:name 'left :expr {:op :literal :value large-left}}
             {:name 'right :expr {:op :literal :value large-right}}]
            :body
            [{:op :builtin-call :function '<
              :args [{:op :local :name 'left}
                     {:op :local :name 'right}]}]})
          nested-plan
          (authenticated-binary-integer-closed-plan
           {:op :builtin-call :function '>=
            :args
            [{:op :if
              :test {:op :literal :value true}
              :then {:op :literal :value large-right}
              :else {:op :literal :value large-left}}
             {:op :literal :value large-right}]})]
      (doseq [[label plan expected]
              [[:large-sequential-locals local-plan true]
               [:large-nested-if nested-plan true]]]
        (is (= :complete
               (:status
                (bootstrap/p15-s23-closed-runtime-plan-validation!
                 (:path (:source plan)) :llvm plan))) label)
        (is (= expected (:entrypoint-result (execute plan))) label)))
    (let [base
          (authenticated-binary-integer-closed-plan
           {:op :builtin-call :function '<
            :args [{:op :literal :value 1}
                   {:op :literal :value 2}]})
          type-hostiles
          [(assoc-in base [:functions 'main :instructions 0 :args 0 :value]
                     "1")
           (assoc-in base [:functions 'main :instructions 0 :args 1 :value]
                     true)
           (authenticated-binary-integer-closed-plan
            {:op :let
             :bindings [{:name 'left
                         :expr {:op :literal :value "not-an-integer"}}]
             :body [{:op :builtin-call :function '>=
                     :args [{:op :local :name 'left}
                            {:op :literal :value 0}]}]})]]
      (doseq [plan type-hostiles]
        (let [data
              (diagnostic-data
               #(bootstrap/p15-s23-closed-runtime-plan-validation!
                 (:path (:source plan)) :llvm plan))]
          (is (= "P15S23X002" (:id data)))
          (is (= :closed-plan-binary-integer-comparison-operands
                 (:missing-fact data)))
          (is (not (str/includes? (pr-str data) "ClassCastException")))))
      (let [arity-data
            (diagnostic-data
             #(bootstrap/p15-s23-closed-runtime-plan-validation!
               (:path (:source base)) :llvm
               (update-in base
                          [:functions 'main :instructions 0 :args]
                          pop)))
            unknown-data
            (diagnostic-data
             #(bootstrap/p15-s23-closed-runtime-plan-validation!
               (:path (:source base)) :llvm
               (assoc-in base
                         [:functions 'main :instructions 0 :function]
                         '+)))]
        (is (= "L2-BUILTIN-ARITY" (:id arity-data)))
        (is (= 2 (:expected-arity arity-data)))
        (is (= "P15S23X002" (:id unknown-data)))
        (is (= :closed-plan-builtin (:missing-fact unknown-data)))))))

(defn- authenticated-binary-integer-llvm-upstream
  [source-path source]
  (binding
   [bootstrap/*p15-s23-c11-mir-diagnostic-context* {:requested-target :llvm}
    bootstrap/*additional-bootstrap-targets*
    bootstrap/stage2-runtime-derived-source-targets]
    (let [context
          (bootstrap/p15-s23-stage2-gravity-checked-core-context
           source-path source :llvm)
          checked-core
          (bootstrap/p15-s23-stage2-gravity-checked-core-source-artifact
           context)
          c11
          (bootstrap/p15-s23-stage2-c11-mir-artifact checked-core context)]
      {:context context :checked-core checked-core :c11 c11})))

(def ^:private authenticated-binary-integer-llvm-b3-plan
  (delay
    (let [path bootstrap/p15-s23-b3-llvm-source-relative-path
          source (slurp path)]
      (bootstrap/p15-s23-stage2-compiler-artifact-plan
       (:emitter
        (bootstrap/c-backend-stage2-plan-emitter-source-rule! path :llvm))
       path source))))

(def ^:private authenticated-binary-integer-llvm-c14-plan
  (delay
    (let [path bootstrap/p15-s23-c14-source-relative-path
          source (slurp path)]
      (bootstrap/p15-s23-stage2-compiler-artifact-plan
       (:emitter
        (bootstrap/c-backend-stage2-plan-emitter-source-rule! path :llvm))
       path source))))

(defn- authenticated-binary-integer-llvm-compiled-lowering
  [mir]
  (bootstrap/p15-s23-stage2-runtime-execute-function
   {:engine :authenticated-integer-llvm-b3-test
    :compiler-artifact-plan? true}
   @authenticated-binary-integer-llvm-b3-plan
   'b3-build-bounded-arm64-macos-llvm [mir]))

(defn- authenticated-binary-integer-llvm-tool-free-row
  [root case]
  (let [source (authenticated-binary-integer-llvm-source case)
        file (.resolve root (str (name (:label case)) (:extension case)))
        _ (spit (.toFile file) source)
        path (.toString
              (.toRealPath file (make-array java.nio.file.LinkOption 0)))
        upstream (authenticated-binary-integer-llvm-upstream path source)
        packet
        (bootstrap/p15-s23-stage2-c13-c14-b1-packet-from-c11!
         (:c11 upstream) (:checked-core upstream) (:context upstream))
        mir (:optimized-mir packet)
        gravity (authenticated-binary-integer-llvm-compiled-lowering mir)
        host (bootstrap/p15-s23-b3-llvm-reconstructed-lowering mir)]
    (assoc case :source source :path path :upstream upstream :packet packet
           :mir mir :gravity gravity :host host)))

(def ^:private authenticated-binary-integer-llvm-gate-a-proof
  (delay
    (with-temp-directory
      "gravity-authenticated-integer-llvm-left-"
      (fn [left-root]
        (with-temp-directory
          "gravity-authenticated-integer-llvm-right-"
          (fn [right-root]
            (let [before
                  (bootstrap/p15-s23-b3-llvm-tool-execution-snapshot)
                  rows
                  (mapv #(authenticated-binary-integer-llvm-tool-free-row
                          left-root %)
                        authenticated-binary-integer-llvm-cases)
                  mirror
                  (assoc
                   (authenticated-binary-integer-llvm-tool-free-row
                    right-root
                    (assoc (first authenticated-binary-integer-llvm-cases)
                           :extension ".qst"))
                   :label :eq-true-mirror)
                  after
                  (bootstrap/p15-s23-b3-llvm-tool-execution-snapshot)]
              {:rows rows :mirror mirror :before before :after after})))))))

(deftest authenticated-binary-integer-comparisons-reach-gravity-b3-llvm
  (let [{:keys [rows mirror before after]}
        @authenticated-binary-integer-llvm-gate-a-proof
        expected-predicates
        {:integer-eq "eq" :integer-lt "slt" :integer-lte "sle"
         :integer-gt "sgt" :integer-gte "sge"}]
    (is (= before after))
    (is (= expected-predicates
           (zipmap (map :source-operation rows) (map :predicate rows))))
    (doseq [{:keys [label source-operation expected predicate extension
                    packet mir gravity host]} rows]
      (let [function (get-in mir [:functions 'main])
            block-order
            (bootstrap/p15-s23-b3-llvm-block-order mir function)
            operations
            (bootstrap/p15-s23-b3-llvm-operation-sequence
             function block-order)
            operation
            (first (filter #(= source-operation (:opcode %)) operations))
            [left-id right-id] (:operands operation)
            operation-index (:operation-index gravity)
            index (get operation-index (:op-id operation))
            record
            (first (filter #(= source-operation (:mir-opcode %))
                           (:operation-records gravity)))
            expected-instruction
            (str "  %cmp" index " = icmp " predicate " i64 "
                 (bootstrap/p15-s23-b3-llvm-value-reference
                  operation-index left-id)
                 ", "
                 (bootstrap/p15-s23-b3-llvm-value-reference
                  operation-index right-id)
                 "\n  %v" index " = zext i1 %cmp" index " to i64")
            ir (:llvm-ir gravity)]
        (is (= :accepted-for-bounded-llvm (:status packet)) label)
        (is (= gravity host) label)
        (is (= :constructed-unverified (:status gravity)) label)
        (is (= [source-operation source-operation :gravity/bool 2]
               ((juxt :opcode :source-operation :type
                      #(count (:operands %))) operation)) label)
        (is (= :not-applicable (:constant-payload operation)) label)
        (is (empty? (:effects operation)) label)
        (is (empty? (:capabilities operation)) label)
        (is (= expected (:semantic-result gravity)) label)
        (is (= (if expected 1 0) (:expected-exit-code gravity)) label)
        (is (= expected-instruction (:llvm-instruction record)) label)
        (is (= [:gravity/bool :i64 (str "%v" index)]
               ((juxt :mir-type :llvm-type :llvm-value) record)) label)
        (is (= 1 (count (re-seq
                         (re-pattern (str "icmp " predicate " i64")) ir)))
            label)
        (is (= 1 (count (re-seq #"zext i1 %cmp[0-9]+ to i64" ir)))
            label)
        (is (not (re-find #"icmp u|sext i1|sub i64| nsw| nuw| undef| poison"
                          ir)) label)
        (is (= [] (:emitted-metadata gravity)) label)
        (is (= [] (:emitted-function-attributes gravity)) label)
        (is (= {} (:proof-to-metadata-map gravity)) label)
        (is (= [] (:ub-sensitive-flags gravity)) label)
        (is (contains? #{".gravity" ".qst"} extension) label)
        (doseq [key [:whole-c13? :whole-c14? :whole-b1? :whole-b3?
                     :public? :release? :self-hosted?]]
          (is (false? (get (:scope packet) key)) [label key]))))
    (doseq [[source-operation grouped] (group-by :source-operation rows)]
      (is (= #{true false} (set (map :expected grouped))) source-operation)
      (is (= #{".gravity" ".qst"} (set (map :extension grouped)))
          source-operation))
    (let [left (first rows)
          right mirror]
      (is (= (:source left) (:source right)))
      (is (= (get-in left [:upstream :checked-core :artifact-id])
             (get-in right [:upstream :checked-core :artifact-id])))
      (is (= (get-in left [:upstream :c11 :mir-id])
             (get-in right [:upstream :c11 :mir-id])))
      (is (= (get-in left [:packet :semantic-id])
             (get-in right [:packet :semantic-id])))
      (is (= (get-in left [:packet :artifact-id])
             (get-in right [:packet :artifact-id])))
      (is (not= (get-in left [:packet :actual-path-binding-id])
                (get-in right [:packet :actual-path-binding-id])))
      (is (= (:path left)
             (get-in left [:packet :actual-path-provenance :source])))
      (is (= (:path right)
             (get-in right [:packet :actual-path-provenance :source])))
      (is (= (:gravity left) (:gravity right))))
    (is (= [:scalar-i64-bool-nil :forwarding :truthiness
            :single-conditional :signed-i64-integer-comparisons]
           (:supported-operation-families bootstrap/p15-s23-b3-llvm-policy)))
    (is (false? (:whole-b3? bootstrap/p15-s23-b3-llvm-policy)))
    (is (false? (:public? bootstrap/p15-s23-b3-llvm-policy)))
    (is (false? (:release? bootstrap/p15-s23-b3-llvm-policy)))
    (is (false? (:self-hosted? bootstrap/p15-s23-b3-llvm-policy)))))

(defn- authenticated-binary-integer-llvm-replace-operation
  [operations operation-id transform]
  (mapv (fn [operation]
          (if (= operation-id (:op-id operation))
            (transform operation)
            operation))
        operations))

(deftest authenticated-binary-integer-comparisons-fail-closed-at-b3
  (let [case (first (filter #(= :lt-true (:label %))
                            authenticated-binary-integer-llvm-cases))
        before (bootstrap/p15-s23-b3-llvm-tool-execution-snapshot)
        row
        (with-temp-directory
          "gravity-authenticated-integer-llvm-hostile-"
          (fn [root]
            (authenticated-binary-integer-llvm-tool-free-row root case)))
        after (bootstrap/p15-s23-b3-llvm-tool-execution-snapshot)
        mir (:mir row)
        function (get-in mir [:functions 'main])
        block-order (bootstrap/p15-s23-b3-llvm-block-order mir function)
        operations
        (bootstrap/p15-s23-b3-llvm-operation-sequence function block-order)
        comparison
        (first (filter #(= :integer-lt (:opcode %)) operations))
        comparison-id (:op-id comparison)
        [left-id right-id] (:operands comparison)
        future-id (:op-id (last operations))
        operation-index (:operation-index (:gravity row))
        block-labels (:block-labels (:gravity row))
        values (get-in mir [:data-flow-graph :values])
        replace-comparison
        (fn [candidate]
          (authenticated-binary-integer-llvm-replace-operation
           operations comparison-id (constantly candidate)))
        cases
        [{:label :source
          :candidate (assoc comparison :source-operation :integer-gte)
          :reason :source-operation-opcode-parity}
         {:label :payload
          :candidate (assoc comparison :constant-payload
                            {:present? true :value 1})
          :values (assoc-in values [comparison-id :constant-payload]
                            {:present? true :value 1})
          :reason :nonconstant-payload-must-be-not-applicable}
         {:label :arity
          :candidate (assoc comparison :operands [left-id])
          :reason :integer-comparison-requires-two-operands}
         {:label :undefined
          :candidate (assoc comparison :operands ["missing-value" right-id])
          :reason :integer-comparison-left-definition}
         {:label :self
          :candidate (assoc comparison :operands [comparison-id right-id])
          :reason :integer-comparison-prior-definition-or-dominance}
         {:label :future
          :candidate (assoc comparison :operands [future-id right-id])
          :reason :integer-comparison-prior-definition-or-dominance}
         {:label :left-type
          :candidate comparison
          :operations
          (authenticated-binary-integer-llvm-replace-operation
           operations left-id #(assoc % :type :gravity/bool))
          :reason :integer-comparison-left-operand-type}
         {:label :right-type
          :candidate comparison
          :operations
          (authenticated-binary-integer-llvm-replace-operation
           operations right-id #(assoc % :type :gravity/bool))
          :reason :integer-comparison-right-operand-type}
         {:label :result-type
          :candidate (assoc comparison :type :gravity/integer)
          :values (assoc-in values [comparison-id :type] :gravity/integer)
          :reason :integer-comparison-result-type}]
        observations
        (mapv
         (fn [{:keys [candidate reason] :as case}]
           (let [candidate-operations
                 (or (:operations case) (replace-comparison candidate))
                 candidate-values (or (:values case) values)]
             (assoc
              case
              :compiled
              (bootstrap/p15-s23-stage2-runtime-execute-function
               {:engine :authenticated-integer-llvm-hostile-b3-test
                :compiler-artifact-plan? true}
               @authenticated-binary-integer-llvm-b3-plan
               'b3-operation-unsupported-reason
               [candidate candidate-operations operation-index block-labels
                candidate-values])
              :host
              (bootstrap/p15-s23-b3-llvm-operation-rejection
               candidate-operations candidate block-labels))))
         cases)
        sibling-then-id "hostile-sibling:mir:then"
        sibling-else-id "hostile-sibling:mir:else"
        sibling-operations
        (-> operations
            (authenticated-binary-integer-llvm-replace-operation
             left-id #(assoc % :block-id sibling-then-id))
            (authenticated-binary-integer-llvm-replace-operation
             comparison-id #(assoc % :block-id sibling-else-id)))
        sibling-comparison
        (first (filter #(= comparison-id (:op-id %)) sibling-operations))
        sibling-block-labels
        (assoc block-labels
               sibling-then-id "then"
               sibling-else-id "else")
        sibling-compiled
        (bootstrap/p15-s23-stage2-runtime-execute-function
         {:engine :authenticated-integer-llvm-sibling-dominance-test
          :compiler-artifact-plan? true}
         @authenticated-binary-integer-llvm-b3-plan
         'b3-operation-unsupported-reason
         [sibling-comparison sibling-operations operation-index
          sibling-block-labels values])
        sibling-host
        (bootstrap/p15-s23-b3-llvm-operation-rejection
         sibling-operations sibling-comparison sibling-block-labels)
        spoof-block-id "hostile-opaque-block"
        spoof-operations
        (authenticated-binary-integer-llvm-replace-operation
         operations comparison-id #(assoc % :block-id spoof-block-id))
        spoof-comparison
        (first (filter #(= comparison-id (:op-id %)) spoof-operations))
        spoof-compiled
        (bootstrap/p15-s23-stage2-runtime-execute-function
         {:engine :authenticated-integer-llvm-spoof-block-test
          :compiler-artifact-plan? true}
         @authenticated-binary-integer-llvm-b3-plan
         'b3-operation-unsupported-reason
         [spoof-comparison spoof-operations operation-index
          block-labels values])
        spoof-host
        (bootstrap/p15-s23-b3-llvm-operation-rejection
         spoof-operations spoof-comparison block-labels)
        source-mismatch
        (assoc comparison :source-operation :integer-gte)
        hostile-mir (c11-update-operation
                     mir comparison-id (constantly source-mismatch))
        full-gravity
        (authenticated-binary-integer-llvm-compiled-lowering hostile-mir)
        hostile-c11
        (assoc-in (get-in row [:upstream :c11]) [:mir-module]
                  (c11-update-operation
                   (get-in row [:upstream :c11 :mir-module]) comparison-id
                   (constantly source-mismatch)))
        host-preflight
        (diagnostic-data
         #(bootstrap/p15-s23-b3-llvm-preflight! hostile-c11))
        final-snapshot
        (bootstrap/p15-s23-b3-llvm-tool-execution-snapshot)]
    (is (= before after final-snapshot))
    (is (nil? (bootstrap/p15-s23-b3-llvm-operation-rejection
               operations comparison)))
    (is (= :integer-comparison-prior-definition-or-dominance
           sibling-compiled sibling-host))
    (is (= :integer-comparison-prior-definition-or-dominance
           spoof-compiled spoof-host))
    (doseq [{:keys [label reason compiled host]} observations]
      (is (= reason compiled) [label :compiled compiled])
      (is (= reason host) [label :host host]))
    (is (= [:rejected "B1-UNSUPPORTED"
            :source-operation-opcode-parity]
           ((juxt :status :diagnostic :missing-fact) full-gravity)))
    (is (= "B1-UNSUPPORTED" (:id host-preflight) (:rule host-preflight)))
    (is (= :source-operation-opcode-parity
           (:missing-fact host-preflight)))
    (is (= :b1-backend-interface (:stage host-preflight)))
    (is (not (str/includes? (pr-str host-preflight)
                            "ClassCastException")))))

(deftest authenticated-binary-integer-llvm-c14-owns-signed-i64-admission
  (let [valid-case (first authenticated-binary-integer-llvm-cases)
        valid-source (authenticated-binary-integer-llvm-source valid-case)
        valid-upstream
        (authenticated-binary-integer-llvm-upstream
         "llvm-c14-valid.gravity" valid-source)
        valid-packet
        (bootstrap/p15-s23-stage2-c13-c14-b1-packet-from-c11!
         (:c11 valid-upstream) (:checked-core valid-upstream)
         (:context valid-upstream))
        valid-c13 (:c13 valid-packet)
        valid-report
        (bootstrap/p15-s23-stage2-c11-mir-verification-report
         (:c11 valid-upstream) (:checked-core valid-upstream)
         (:context valid-upstream))
